globalThis.DEClic_BUILTINS = [{"id": "marketing", "title": "Marketing", "description": "164 questions pour réviser toutes les notions du cours.", "symbol": "M", "storageKey": "declic-marketing-concepts-v3", "cards": [{"id": "marketing-concept-001", "chapter": "Bases du marketing", "question": "Quelle est la définition du marketing ?", "answer": "Le marketing regroupe les activités qui permettent de comprendre les besoins et désirs, de concevoir une offre adaptée et de créer, communiquer et délivrer de la valeur. Il vise des relations durables avec les clients.", "sources": [{"documentId": "mf", "page": 1}]}, {"id": "marketing-concept-002", "chapter": "Bases du marketing", "question": "Qu’est-ce qu’un besoin ?", "answer": "Un besoin est un état de manque lié à la nature humaine. Il peut être physique, social ou individuel."}, {"id": "marketing-concept-003", "chapter": "Bases du marketing", "question": "Qu’est-ce qu’un désir ?", "answer": "Un désir est la forme précise que prend un besoin sous l’influence de la culture et de la personnalité."}, {"id": "marketing-concept-004", "chapter": "Bases du marketing", "question": "Qu’est-ce que la demande ?", "answer": "La demande correspond aux produits ou services que les consommateurs veulent et peuvent acheter, à un prix donné et pendant une période donnée."}, {"id": "marketing-concept-005", "chapter": "Bases du marketing", "question": "Quelle différence y a-t-il entre besoin, désir et demande ?", "answer": "Le besoin est un manque. Le désir est la réponse précise souhaitée. La demande suppose une volonté d’achat et un pouvoir d’achat suffisant."}, {"id": "marketing-concept-006", "chapter": "Bases du marketing", "question": "Quels sont les cinq niveaux de besoins de Maslow ?", "answer": "Besoins physiologiques, sécurité, appartenance, estime et accomplissement de soi."}, {"id": "marketing-concept-007", "chapter": "Bases du marketing", "question": "Quels sont les cinq types de besoins distingués par Kotler ?", "answer": "Besoins exprimés, réels, latents, rêvés et profonds. Ils correspondent à ce que le client dit, veut dire, n’envisage pas encore, rêve d’obtenir ou recherche plus secrètement."}, {"id": "marketing-concept-008", "chapter": "Bases du marketing", "question": "Qu’est-ce qu’une offre commerciale ?", "answer": "C’est un bien ou un service proposé sur un marché pour satisfaire un besoin ou un désir.", "sources": [{"documentId": "mf", "page": 4}]}, {"id": "marketing-concept-009", "chapter": "Bases du marketing", "question": "Quelle est la différence entre un bien et un service ?", "answer": "Un bien est tangible, alors qu’un service est intangible.", "sources": [{"documentId": "mf", "page": 4}]}, {"id": "marketing-concept-010", "chapter": "Bases du marketing", "question": "Qu’est-ce que la myopie marketing ?", "answer": "C’est le fait de se concentrer sur le produit lui-même plutôt que sur les besoins, bénéfices ou expériences recherchés par les clients."}, {"id": "marketing-concept-011", "chapter": "Bases du marketing", "question": "Qu’est-ce que la valeur perçue ?", "answer": "C’est la différence entre les bénéfices perçus et les coûts perçus par le client. Elle est subjective."}, {"id": "marketing-concept-012", "chapter": "Bases du marketing", "question": "Qu’est-ce que la satisfaction du client ?", "answer": "Elle résulte de la comparaison entre les attentes du client et l’expérience qu’il a réellement vécue."}, {"id": "marketing-concept-013", "chapter": "Bases du marketing", "question": "Quelle est la différence entre un client et un prospect ?", "answer": "Un client a déjà acheté. Un prospect est un client potentiel qui n’a pas encore acheté."}, {"id": "marketing-concept-014", "chapter": "Bases du marketing", "question": "Que signifient B2C, B2B et C2C ?", "answer": "B2C : entreprise vers consommateur. B2B : entreprise vers entreprise. C2C : échanges entre consommateurs."}, {"id": "marketing-concept-015", "chapter": "Démarche et orientations", "question": "Quelles sont les trois phases de la démarche marketing ?", "answer": "Le marketing d’études, le marketing stratégique et le marketing opérationnel. Le contrôle permet de mesurer les résultats et de corriger les actions."}, {"id": "marketing-concept-016", "chapter": "Démarche et orientations", "question": "Qu’est-ce que le marketing d’études ?", "answer": "Il consiste à recueillir et analyser des informations sur le marché, l’entreprise et son environnement pour comprendre la situation."}, {"id": "marketing-concept-017", "chapter": "Démarche et orientations", "question": "Qu’est-ce que le marketing stratégique ?", "answer": "Il consiste notamment à choisir les segments à servir et à définir une offre et un positionnement adaptés.", "sources": [{"documentId": "mf", "page": 3}]}, {"id": "marketing-concept-018", "chapter": "Démarche et orientations", "question": "Qu’est-ce que le marketing opérationnel ?", "answer": "Il met en œuvre les actions marketing autour du produit, du prix, de la distribution et de la communication.", "sources": [{"documentId": "mf", "page": 3}]}, {"id": "marketing-concept-019", "chapter": "Démarche et orientations", "question": "Qu’est-ce qu’une étude documentaire ?", "answer": "C’est l’exploitation d’informations déjà disponibles. Elle est rapide et peu coûteuse, mais les données peuvent être trop générales ou peu adaptées."}, {"id": "marketing-concept-020", "chapter": "Démarche et orientations", "question": "Quelle différence y a-t-il entre une étude qualitative et une étude quantitative ?", "answer": "L’étude qualitative cherche à comprendre les motivations, notamment par des entretiens. L’étude quantitative mesure des phénomènes, notamment par des sondages."}, {"id": "marketing-concept-021", "chapter": "Démarche et orientations", "question": "Qu’est-ce que l’orientation production ?", "answer": "Elle donne la priorité à la capacité de production, à la productivité, à la baisse des coûts et à la disponibilité des produits."}, {"id": "marketing-concept-022", "chapter": "Démarche et orientations", "question": "Qu’est-ce que l’orientation produit ?", "answer": "Elle repose sur l’idée que le consommateur choisit le produit offrant la meilleure qualité ou les meilleures performances techniques."}, {"id": "marketing-concept-023", "chapter": "Démarche et orientations", "question": "Qu’est-ce que l’orientation vente ?", "answer": "Elle consiste à chercher à faire accepter et acheter ce qui a été produit, grâce à la pression commerciale et publicitaire."}, {"id": "marketing-concept-024", "chapter": "Démarche et orientations", "question": "Qu’est-ce que l’orientation marketing ?", "answer": "Elle part des besoins et attentes des consommateurs pour concevoir les produits et services susceptibles de les satisfaire."}, {"id": "marketing-concept-025", "chapter": "Démarche et orientations", "question": "Qu’est-ce que le marketing sociétal ?", "answer": "Il recherche un équilibre entre les désirs des consommateurs, les objectifs de l’entreprise et le bien-être collectif à long terme."}, {"id": "marketing-concept-026", "chapter": "Environnement", "question": "Qu’est-ce que le macro-environnement ?", "answer": "C’est l’ensemble des grandes forces externes que l’organisation ne contrôle pas directement mais auxquelles elle doit s’adapter."}, {"id": "marketing-concept-027", "chapter": "Environnement", "question": "Qu’est-ce que le micro-environnement ?", "answer": "Il est constitué des acteurs proches avec lesquels l’organisation interagit pour mener sa stratégie marketing."}, {"id": "marketing-concept-028", "chapter": "Environnement", "question": "Que signifie PESTEL ?", "answer": "Politique, économique, socioculturel, technologique, écologique et légal. Cet outil sert à analyser le macro-environnement."}, {"id": "marketing-concept-029", "chapter": "Environnement", "question": "Quels sont les principaux acteurs du micro-environnement ?", "answer": "Les acheteurs et consommateurs, les fournisseurs, les concurrents, les prescripteurs, les intermédiaires et les groupes d’influence."}, {"id": "marketing-concept-030", "chapter": "Environnement", "question": "Quelle différence y a-t-il entre un acheteur et un consommateur ?", "answer": "L’acheteur effectue l’achat ; le consommateur utilise le produit ou le service. Ce peut être la même personne ou deux personnes différentes.", "sources": [{"documentId": "mf", "page": 7}]}, {"id": "marketing-concept-031", "chapter": "Environnement", "question": "Qu’est-ce qu’un prescripteur ?", "answer": "C’est une personne ou une organisation qui influence la décision d’achat par ses conseils ou recommandations, sans nécessairement acheter."}, {"id": "marketing-concept-032", "chapter": "Environnement", "question": "Quelle différence y a-t-il entre concurrence directe et indirecte ?", "answer": "La concurrence directe propose des produits ou services identiques ou très proches. La concurrence indirecte propose des solutions différentes répondant au même besoin."}, {"id": "marketing-concept-033", "chapter": "Environnement", "question": "Qu’est-ce qu’un monopole ?", "answer": "C’est une structure de marché dans laquelle une seule entreprise propose l’offre considérée."}, {"id": "marketing-concept-034", "chapter": "Environnement", "question": "Qu’est-ce qu’un oligopole ?", "answer": "C’est une structure de marché dans laquelle quelques entreprises se partagent l’offre."}, {"id": "marketing-concept-035", "chapter": "Environnement", "question": "Quelles sont les cinq forces de Porter ?", "answer": "La rivalité entre concurrents, la menace des nouveaux entrants, la menace des substituts, le pouvoir de négociation des fournisseurs et le pouvoir de négociation des clients."}, {"id": "marketing-concept-036", "chapter": "Environnement", "question": "Qu’est-ce qu’une tendance de marché ?", "answer": "C’est une évolution durable des comportements, attentes ou technologies qui influence l’offre et la demande."}, {"id": "marketing-concept-037", "chapter": "Marché", "question": "Quelle est la définition d’un marché ?", "answer": "Un marché est le lieu de rencontre entre l’offre et la demande permettant des transactions. Il peut être physique ou virtuel."}, {"id": "marketing-concept-038", "chapter": "Marché", "question": "Quelle différence y a-t-il entre un marché atomisé et un marché concentré ?", "answer": "Un marché atomisé est partagé entre de nombreux acteurs. Un marché concentré compte peu d’entreprises qui occupent une place importante."}, {"id": "marketing-concept-039", "chapter": "Marché", "question": "Qu’est-ce que le marché principal ?", "answer": "Il regroupe les produits techniquement identiques et directement concurrents."}, {"id": "marketing-concept-040", "chapter": "Marché", "question": "Qu’est-ce que le marché environnant ?", "answer": "Il regroupe les produits de nature différente qui peuvent se substituer aux produits du marché principal pour satisfaire le même besoin."}, {"id": "marketing-concept-041", "chapter": "Marché", "question": "Qu’est-ce que le marché générique ?", "answer": "Il regroupe les produits liés à la catégorie générale de besoins satisfaite par les produits du marché principal."}, {"id": "marketing-concept-042", "chapter": "Marché", "question": "Qu’est-ce que le marché support ?", "answer": "Il regroupe les produits associés ou complémentaires à la consommation des produits considérés."}, {"id": "marketing-concept-043", "chapter": "Marché", "question": "Qu’est-ce que le marché réel ?", "answer": "Il correspond aux consommateurs qui ont acheté le produit pendant une période donnée."}, {"id": "marketing-concept-044", "chapter": "Marché", "question": "Qu’est-ce que le marché potentiel ?", "answer": "Il rassemble les consommateurs actuels et les non-consommateurs relatifs."}, {"id": "marketing-concept-045", "chapter": "Marché", "question": "Quelle différence y a-t-il entre un non-consommateur relatif et un non-consommateur absolu ?", "answer": "Le non-consommateur relatif pourrait devenir consommateur. Le non-consommateur absolu ne peut pas ou ne veut durablement pas consommer le produit dans le cadre étudié."}, {"id": "marketing-concept-046", "chapter": "Marché", "question": "Quelle différence y a-t-il entre un marché en volume et un marché en valeur ?", "answer": "Le volume mesure les quantités physiques vendues. La valeur mesure le montant monétaire des ventes."}, {"id": "marketing-concept-047", "chapter": "Marché", "question": "Comment calcule-t-on le taux de croissance d’un marché ?", "answer": "Taux de croissance (%) = (valeur d’arrivée - valeur de départ) / valeur de départ × 100."}, {"id": "marketing-concept-048", "chapter": "Marché", "question": "Comment calcule-t-on une part de marché absolue ?", "answer": "Part de marché (%) = ventes de l’entreprise / ventes totales du marché × 100. Le calcul peut se faire en volume ou en valeur.", "sources": [{"documentId": "mf", "page": 2}]}, {"id": "marketing-concept-049", "chapter": "Marché", "question": "Comment calcule-t-on une part de marché relative ?", "answer": "Part de marché relative = part de marché de l’entreprise / part de marché de son principal concurrent. C’est un ratio.", "sources": [{"documentId": "mf", "page": 2}]}, {"id": "marketing-concept-050", "chapter": "Marché", "question": "Comment interprète-t-on une part de marché relative ?", "answer": "Supérieure à 1 : l’entreprise dépasse son principal concurrent. Égale à 1 : elles réalisent les mêmes ventes. Inférieure à 1 : l’entreprise est derrière.", "sources": [{"documentId": "mf", "page": 2}]}, {"id": "marketing-concept-051", "chapter": "Marché", "question": "Comment calcule-t-on le taux de pénétration ?", "answer": "Taux de pénétration (%) = marché réel / marché potentiel × 100.", "sources": [{"documentId": "mf", "page": 2}]}, {"id": "marketing-concept-052", "chapter": "Marché", "question": "Quelles sont les quatre phases du cycle de vie d’un marché ?", "answer": "Naissance, croissance, maturité et déclin.", "sources": [{"documentId": "mf", "page": 2}]}, {"id": "marketing-concept-053", "chapter": "Diagnostic et stratégie", "question": "Qu’est-ce qu’une analyse interne ?", "answer": "C’est l’analyse des ressources, compétences, fonctionnement et politique marketing de l’organisation pour identifier ses forces et ses faiblesses.", "sources": [{"documentId": "mf", "page": 2}]}, {"id": "marketing-concept-054", "chapter": "Diagnostic et stratégie", "question": "À quoi sert la chaîne de valeur de Porter ?", "answer": "Elle identifie les activités qui créent de la valeur et permet d’en analyser les coûts.", "sources": [{"documentId": "mf", "page": 2}]}, {"id": "marketing-concept-055", "chapter": "Diagnostic et stratégie", "question": "Qu’est-ce que la notoriété d’une marque ?", "answer": "C’est le degré de connaissance d’une marque et de sa catégorie de produits par le public.", "sources": [{"documentId": "mf", "page": 3}]}, {"id": "marketing-concept-056", "chapter": "Diagnostic et stratégie", "question": "Quelle différence y a-t-il entre notoriété spontanée, top of mind et notoriété assistée ?", "answer": "Spontanée : la marque est citée sans aide. Top of mind : elle est citée en premier. Assistée : elle est reconnue à partir d’une liste.", "sources": [{"documentId": "mf", "page": 3}]}, {"id": "marketing-concept-057", "chapter": "Diagnostic et stratégie", "question": "Qu’est-ce que l’image de marque ?", "answer": "C’est l’ensemble des représentations et associations que les consommateurs attachent à une marque."}, {"id": "marketing-concept-058", "chapter": "Diagnostic et stratégie", "question": "Quelles sont les stratégies génériques de Porter ?", "answer": "La domination par les coûts, la différenciation et la concentration ou focalisation."}, {"id": "marketing-concept-059", "chapter": "Diagnostic et stratégie", "question": "Que signifie SWOT ?", "answer": "Strengths, Weaknesses, Opportunities, Threats : forces, faiblesses, opportunités et menaces.", "sources": [{"documentId": "mf", "page": 3}]}, {"id": "marketing-concept-060", "chapter": "Diagnostic et stratégie", "question": "Quelle différence y a-t-il entre les éléments internes et externes du SWOT ?", "answer": "Les forces et faiblesses sont internes à l’organisation. Les opportunités et menaces viennent de l’environnement externe.", "sources": [{"documentId": "mf", "page": 3}]}, {"id": "marketing-concept-061", "chapter": "Diagnostic et stratégie", "question": "Quelles sont les quatre fonctions du pilotage marketing ?", "answer": "Analyse, planification, implémentation et contrôle. La démarche est itérative.", "sources": [{"documentId": "mf", "page": 3}]}, {"id": "marketing-concept-062", "chapter": "Diagnostic et stratégie", "question": "Qu’est-ce que l’implémentation marketing ?", "answer": "C’est la mise en œuvre concrète de la stratégie prévue dans le plan marketing : qui agit, où, quand et comment.", "sources": [{"documentId": "mf", "page": 4}]}, {"id": "marketing-concept-063", "chapter": "Diagnostic et stratégie", "question": "Quelles sont les trois étapes du contrôle marketing ?", "answer": "Mesurer les performances, comparer les résultats aux objectifs, puis mettre en place des actions correctrices.", "sources": [{"documentId": "mf", "page": 4}]}, {"id": "marketing-concept-064", "chapter": "Diagnostic et stratégie", "question": "Quelles sont les quatre stratégies de croissance d’Ansoff ?", "answer": "Pénétration de marché : produits et marchés existants. Développement de marché : produits existants et nouveaux marchés. Développement de produits : nouveaux produits et marchés existants. Diversification : nouveaux produits et nouveaux marchés.", "sources": [{"documentId": "mf", "page": 4}]}, {"id": "marketing-concept-065", "chapter": "Marketing mix", "question": "Qu’est-ce que le marketing mix ?", "answer": "C’est l’ensemble cohérent des outils dont dispose l’entreprise pour atteindre ses objectifs sur le marché visé.", "sources": [{"documentId": "mf", "page": 4}]}, {"id": "marketing-concept-066", "chapter": "Marketing mix", "question": "Quels sont les 4P ?", "answer": "Product : produit. Price : prix. Place : distribution. Promotion : communication.", "sources": [{"documentId": "mf", "page": 3}]}, {"id": "marketing-concept-067", "chapter": "Marketing mix", "question": "Quelles sont les trois dimensions du produit ?", "answer": "Les caractéristiques techniques, commerciales et psychologiques.", "sources": [{"documentId": "mf", "page": 4}]}, {"id": "marketing-concept-068", "chapter": "Marketing mix", "question": "Quelle différence y a-t-il entre produit intrinsèque, standard et global ?", "answer": "Le produit intrinsèque réunit les caractéristiques fondamentales. Le produit standard comprend sa présentation commerciale et sa marque. Le produit global ajoute les services associés, comme la garantie et le SAV."}, {"id": "marketing-concept-069", "chapter": "Marketing mix", "question": "Qu’est-ce que le capital marque ?", "answer": "C’est l’effet de la connaissance de la marque sur la manière dont les consommateurs réagissent à son marketing."}, {"id": "marketing-concept-070", "chapter": "Marketing mix", "question": "Quelles sont les fonctions du packaging ?", "answer": "Fonctions techniques : protéger, conserver et faciliter l’utilisation, le transport et le stockage. Fonctions marketing : informer, identifier le produit, exprimer le positionnement et favoriser l’achat.", "sources": [{"documentId": "mf", "page": 4}]}, {"id": "marketing-concept-071", "chapter": "Marketing mix", "question": "Quels facteurs influencent la fixation du prix ?", "answer": "Les coûts, la demande et la valeur perçue, les prix des concurrents, les objectifs de l’organisation, les contraintes légales et les tests de prix.", "sources": [{"documentId": "mf", "page": 4}]}, {"id": "marketing-concept-072", "chapter": "Marketing mix", "question": "Qu’est-ce qu’une politique d’écrémage ?", "answer": "C’est une politique de lancement à prix élevé, destinée aux consommateurs les plus intéressés et solvables."}, {"id": "marketing-concept-073", "chapter": "Marketing mix", "question": "Qu’est-ce qu’une politique de pénétration tarifaire ?", "answer": "C’est une politique de lancement à prix bas pour attirer rapidement de nombreux acheteurs et gagner une part de marché importante."}, {"id": "marketing-concept-074", "chapter": "Marketing mix", "question": "Qu’est-ce que la distribution ?", "answer": "C’est l’ensemble des choix et actions qui rendent le produit ou service accessible au consommateur final."}, {"id": "marketing-concept-075", "chapter": "Marketing mix", "question": "Qu’est-ce qu’un circuit de distribution direct ?", "answer": "C’est un circuit dans lequel le producteur vend directement au consommateur, sans intermédiaire."}, {"id": "marketing-concept-076", "chapter": "Marketing mix", "question": "Qu’est-ce que la distribution multicanale ?", "answer": "C’est l’utilisation de plusieurs canaux de distribution pour rendre l’offre accessible aux clients."}, {"id": "marketing-concept-077", "chapter": "Marketing mix", "question": "Quelle différence y a-t-il entre communication interne et externe ?", "answer": "La communication interne s’adresse aux membres de l’organisation. La communication externe s’adresse aux publics extérieurs, notamment aux clients et prospects."}, {"id": "marketing-concept-078", "chapter": "Marketing mix", "question": "Quels sont les trois objectifs de communication ?", "answer": "Cognitif : faire connaître. Affectif : faire aimer. Conatif : faire agir."}, {"id": "marketing-concept-079", "chapter": "Marketing mix", "question": "Que signifie le modèle POEM ?", "answer": "Paid : médias payants. Owned : supports maîtrisés par la marque. Earned : visibilité obtenue auprès de tiers."}, {"id": "marketing-concept-080", "chapter": "Marketing mix", "question": "Qu’est-ce que le greenwashing ?", "answer": "C’est l’utilisation trompeuse ou opportuniste d’arguments environnementaux pour donner une image plus responsable que les pratiques réelles."}, {"id": "marketing-concept-081", "chapter": "Segmentation", "question": "Quelle est la définition de la segmentation ?", "answer": "La segmentation consiste à découper un marché en groupes de consommateurs qui partagent des besoins, caractéristiques ou comportements communs.", "sources": [{"documentId": "mf", "page": 5}]}, {"id": "marketing-concept-082", "chapter": "Segmentation", "question": "Quels sont les principaux critères de segmentation ?", "answer": "Critères géographiques, sociodémographiques, psychographiques, avantages recherchés, comportements et caractéristiques physiques.", "sources": [{"documentId": "mf", "page": 5}]}, {"id": "marketing-concept-083", "chapter": "Segmentation", "question": "Qu’est-ce que la segmentation psychographique ?", "answer": "Elle regroupe les consommateurs selon leur personnalité, leur style de vie, leurs valeurs et leurs motivations.", "sources": [{"documentId": "mf", "page": 5}]}, {"id": "marketing-concept-084", "chapter": "Segmentation", "question": "Qu’est-ce que la segmentation comportementale ?", "answer": "Elle regroupe les consommateurs à partir de comportements observables : fréquence, quantité, occasion ou mode de consommation.", "sources": [{"documentId": "mf", "page": 5}]}, {"id": "marketing-concept-085", "chapter": "Segmentation", "question": "Qu’est-ce que la segmentation par avantages recherchés ?", "answer": "Elle regroupe les consommateurs selon les bénéfices qu’ils attendent du produit.", "sources": [{"documentId": "mf", "page": 5}]}, {"id": "marketing-concept-086", "chapter": "Segmentation", "question": "Qu’est-ce que la segmentation multicritère ?", "answer": "Elle combine plusieurs critères pour former des segments plus précis et plus homogènes, mais généralement plus petits.", "sources": [{"documentId": "mf", "page": 5}]}, {"id": "marketing-concept-087", "chapter": "Segmentation", "question": "Quelles sont les qualités d’un segment utile ?", "answer": "Un segment doit être différenciable, mesurable, accessible, substantiel, pertinent et actualisable. Il réunit des consommateurs aux caractéristiques homogènes.", "sources": [{"documentId": "mf", "page": 7}]}, {"id": "marketing-concept-088", "chapter": "Segmentation", "question": "Quelle différence y a-t-il entre segmentation de l’offre et de la demande ?", "answer": "La segmentation de l’offre regroupe les produits et services. La segmentation de la demande regroupe les consommateurs ou les entreprises clientes.", "sources": [{"documentId": "mf", "page": 6}]}, {"id": "marketing-concept-089", "chapter": "Segmentation", "question": "Qu’est-ce que la segmentation descendante ?", "answer": "Elle découpe successivement la population selon des critères choisis à l’avance. On l’appelle aussi segmentation a priori.", "sources": [{"documentId": "mf", "page": 7}]}, {"id": "marketing-concept-090", "chapter": "Segmentation", "question": "Qu’est-ce que la segmentation ascendante ?", "answer": "Elle regroupe les individus selon leurs ressemblances à partir de nombreuses données. On l’appelle aussi segmentation typologique.", "sources": [{"documentId": "mf", "page": 8}]}, {"id": "marketing-concept-091", "chapter": "Segmentation", "question": "Quels critères permettent de segmenter un marché B2B ?", "answer": "Le secteur d’activité, la taille, les performances économiques, la localisation, le processus de décision, les critères de choix des fournisseurs et la fidélité.", "sources": [{"documentId": "mf", "page": 7}]}, {"id": "marketing-concept-092", "chapter": "Ciblage", "question": "Quelle est la définition du ciblage ?", "answer": "Le ciblage consiste à évaluer les segments puis à choisir celui ou ceux sur lesquels l’entreprise concentrera ses efforts.", "sources": [{"documentId": "mf", "page": 5}]}, {"id": "marketing-concept-093", "chapter": "Ciblage", "question": "Sur quels critères choisit-on une cible ?", "answer": "On évalue l’attractivité du segment et sa compatibilité avec les objectifs, ressources et compétences de l’entreprise.", "sources": [{"documentId": "mf", "page": 8}]}, {"id": "marketing-concept-094", "chapter": "Ciblage", "question": "Qu’est-ce que le ciblage indifférencié ?", "answer": "Il consiste à proposer une offre commune à l’ensemble du marché, en privilégiant les besoins partagés.", "sources": [{"documentId": "mf", "page": 5}]}, {"id": "marketing-concept-095", "chapter": "Ciblage", "question": "Qu’est-ce que le ciblage différencié ?", "answer": "Il consiste à servir plusieurs segments avec une offre et un marketing mix adaptés à chacun.", "sources": [{"documentId": "mf", "page": 5}]}, {"id": "marketing-concept-096", "chapter": "Ciblage", "question": "Qu’est-ce que le ciblage concentré ?", "answer": "Il consiste à concentrer les efforts sur un segment particulier. Une niche est un segment particulièrement étroit et spécifique.", "sources": [{"documentId": "mf", "page": 9}]}, {"id": "marketing-concept-097", "chapter": "Ciblage", "question": "Qu’est-ce que le marketing individualisé ?", "answer": "C’est l’adaptation de tout ou partie de l’offre à chaque individu. On l’appelle aussi marketing one to one.", "sources": [{"documentId": "mf", "page": 9}]}, {"id": "marketing-concept-098", "chapter": "Ciblage", "question": "Qu’est-ce qu’un persona ?", "answer": "C’est un personnage fictif représentant un groupe de clients, construit à partir de données réelles sur leurs profils, comportements et motivations."}, {"id": "marketing-concept-099", "chapter": "Positionnement", "question": "Quelle est la définition du positionnement ?", "answer": "Le positionnement vise à donner à l’offre une place claire et distinctive dans l’esprit des clients ciblés, par rapport aux concurrents.", "sources": [{"documentId": "mf", "page": 9}]}, {"id": "marketing-concept-100", "chapter": "Positionnement", "question": "Quelles sont les deux composantes du positionnement ?", "answer": "L’identification, qui rattache l’offre à une catégorie, et la différenciation, qui la distingue des offres concurrentes.", "sources": [{"documentId": "mf", "page": 6}]}, {"id": "marketing-concept-101", "chapter": "Positionnement", "question": "Qu’est-ce que la différenciation ?", "answer": "C’est le choix d’attributs ou de bénéfices valorisés par la cible qui distinguent l’offre de celle des concurrents.", "sources": [{"documentId": "mf", "page": 6}]}, {"id": "marketing-concept-102", "chapter": "Positionnement", "question": "Comment formule-t-on un énoncé de positionnement ?", "answer": "« Pour [cible], la marque X est [catégorie] qui apporte [bénéfice distinctif]. »", "sources": [{"documentId": "mf", "page": 6}]}, {"id": "marketing-concept-103", "chapter": "Positionnement", "question": "Quels sont les critères d’un bon positionnement ?", "answer": "Il doit être attractif, différenciant, crédible, simple, profitable et pérenne.", "sources": [{"documentId": "mf", "page": 9}]}, {"id": "marketing-concept-104", "chapter": "Positionnement", "question": "Que signifie USP ?", "answer": "Unique Selling Proposition : une proposition de vente unique qui met en avant un bénéfice principal et distinctif.", "sources": [{"documentId": "mf", "page": 9}]}, {"id": "marketing-concept-105", "chapter": "Bases du marketing", "question": "Quels sont les principaux objectifs du marketing ?", "answer": "Attirer de nouveaux clients, conserver les clients existants, satisfaire leurs besoins et créer de la valeur pour construire des relations durables et rentables.", "sources": [{"documentId": "mf", "page": 1}]}, {"id": "marketing-concept-106", "chapter": "Démarche et orientations", "question": "Quelles sont les quatre actions de la démarche marketing présentées dans la fiche ?", "answer": "Étudier le marché et les besoins, repérer la concurrence, définir les objectifs, puis déterminer les moyens d’action pour les atteindre.", "sources": [{"documentId": "mf", "page": 1}]}, {"id": "marketing-concept-107", "chapter": "Bases du marketing", "question": "Pourquoi le marketing est-il utile au lancement d’un produit ?", "answer": "Il aide à comprendre le marché et son environnement, à valoriser l’offre et à limiter les risques liés au lancement.", "sources": [{"documentId": "mf", "page": 1}]}, {"id": "marketing-concept-108", "chapter": "Bases du marketing", "question": "Pourquoi le marketing ne concerne-t-il pas seulement les entreprises commerciales ?", "answer": "Ses principes s’appliquent aussi à d’autres organisations et activités. Il aide à atteindre des objectifs grâce à une démarche organisée et structurée.", "sources": [{"documentId": "mf", "page": 1}]}, {"id": "marketing-concept-109", "chapter": "Bases du marketing", "question": "Comment le marketing crée-t-il de la valeur pour les clients et pour l’organisation ?", "answer": "L’organisation conçoit une offre adaptée aux besoins des clients et construit avec eux des relations rentables. Les clients obtiennent de la valeur, et l’organisation en reçoit en retour.", "sources": [{"documentId": "mf", "page": 1}]}, {"id": "marketing-concept-110", "chapter": "Bases du marketing", "question": "Pourquoi le marketing cherche-t-il à fidéliser les clients ?", "answer": "Pour conserver la clientèle et construire des relations durables et rentables, plutôt que de dépendre uniquement de l’acquisition de nouveaux clients.", "sources": [{"documentId": "mf", "page": 1}]}, {"id": "marketing-concept-111", "chapter": "Bases du marketing", "question": "Quelle est la place des besoins et des désirs dans la conception d’une offre ?", "answer": "Ils constituent le point de départ : l’organisation cherche à les déterminer ou à les anticiper afin de proposer des produits ou services adaptés.", "sources": [{"documentId": "mf", "page": 1}]}, {"id": "marketing-concept-112", "chapter": "Bases du marketing", "question": "Quelles évolutions de l’offre et de la demande expliquent l’évolution du marketing ?", "answer": "Les entreprises cherchent à satisfaire et fidéliser les clients en se différenciant. Les consommateurs changent leurs habitudes et accordent davantage d’importance aux enjeux sociétaux et environnementaux.", "sources": [{"documentId": "mf", "page": 1}]}, {"id": "marketing-concept-113", "chapter": "Marché", "question": "Que mesure une part de marché absolue ?", "answer": "La proportion des ventes totales du marché réalisée par une entreprise. Elle situe son poids dans l’ensemble du marché.", "sources": [{"documentId": "mf", "page": 2}]}, {"id": "marketing-concept-114", "chapter": "Marché", "question": "Pourquoi comparer une part de marché absolue et une part de marché relative ?", "answer": "La part absolue mesure le poids de l’entreprise dans le marché entier. La part relative compare sa position à celle de son principal concurrent.", "sources": [{"documentId": "mf", "page": 2}]}, {"id": "marketing-concept-115", "chapter": "Marché", "question": "Comment interpréter un faible taux de pénétration ?", "answer": "Une part limitée du marché potentiel est déjà consommatrice. Cela indique un potentiel de croissance encore important pour les entreprises du marché.", "sources": [{"documentId": "mf", "page": 2}]}, {"id": "marketing-concept-116", "chapter": "Marché", "question": "Pourquoi distinguer le cycle de vie d’un marché de celui d’un produit ?", "answer": "Le marché et un produit particulier peuvent se trouver à des phases différentes. La maturité du marché ne signifie pas que tous les produits qui le composent sont eux-mêmes à maturité.", "sources": [{"documentId": "mf", "page": 2}]}, {"id": "marketing-concept-117", "chapter": "Diagnostic et stratégie", "question": "Quels sont les objectifs d’un diagnostic interne ?", "answer": "Évaluer les atouts de l’organisation, repérer ses limites et ses dysfonctionnements, puis préparer l’identification des forces et faiblesses dans le SWOT.", "sources": [{"documentId": "mf", "page": 2}]}, {"id": "marketing-concept-118", "chapter": "Diagnostic et stratégie", "question": "Quelles ressources matérielles et financières peut-on examiner dans une analyse interne ?", "answer": "La qualité, la quantité et la modernité des équipements, le business model et la capacité d’investissement.", "sources": [{"documentId": "mf", "page": 2}]}, {"id": "marketing-concept-119", "chapter": "Diagnostic et stratégie", "question": "Quelles ressources immatérielles peut-on examiner dans une analyse interne ?", "answer": "Le savoir-faire, les brevets, les innovations, les certifications, les engagements, le réseau de partenaires et la recherche-développement.", "sources": [{"documentId": "mf", "page": 2}]}, {"id": "marketing-concept-120", "chapter": "Diagnostic et stratégie", "question": "Quels éléments de l’organisation et du fonctionnement faut-il analyser ?", "answer": "La structure, les processus décisionnels, la culture, la communication interne, la gestion de projet, l’adaptation des équipes, la logistique et l’internationalisation.", "sources": [{"documentId": "mf", "page": 3}]}, {"id": "marketing-concept-121", "chapter": "Diagnostic et stratégie", "question": "Quels éléments des ressources humaines faut-il analyser ?", "answer": "La taille des équipes, les compétences, l’expertise, l’expérience, le climat social, la motivation et le style de management.", "sources": [{"documentId": "mf", "page": 3}]}, {"id": "marketing-concept-122", "chapter": "Diagnostic et stratégie", "question": "Comment relier les analyses interne et externe au diagnostic stratégique ?", "answer": "L’analyse interne met en évidence les forces et les faiblesses. L’analyse externe repère les opportunités et les menaces. Leur combinaison forme le diagnostic stratégique SWOT.", "sources": [{"documentId": "mf", "page": 3}]}, {"id": "marketing-concept-123", "chapter": "Diagnostic et stratégie", "question": "Quels objectifs poursuit l’analyse SWOT ?", "answer": "Combler les faiblesses, développer les forces, identifier et anticiper les menaces, faire correspondre les forces aux opportunités et surmonter les menaces.", "sources": [{"documentId": "mf", "page": 3}]}, {"id": "marketing-concept-124", "chapter": "Diagnostic et stratégie", "question": "Quelles questions poser pour interpréter les résultats d’un SWOT ?", "answer": "Les forces compensent-elles les faiblesses ? Permettent-elles de faire face aux menaces ? Permettent-elles de profiter des opportunités ?", "sources": [{"documentId": "mf", "page": 3}]}, {"id": "marketing-concept-125", "chapter": "Diagnostic et stratégie", "question": "Que définit un plan marketing pour un produit ou une marque ?", "answer": "Il fixe les objectifs, précise ce que l’organisation veut faire et détaille la stratégie ainsi que les activités nécessaires pour atteindre ces objectifs.", "sources": [{"documentId": "mf", "page": 4}]}, {"id": "marketing-concept-126", "chapter": "Diagnostic et stratégie", "question": "Pourquoi la démarche marketing est-elle itérative ?", "answer": "Les résultats du contrôle servent à corriger les actions et à adapter la démarche. L’analyse, la planification, la mise en œuvre et le contrôle forment un processus renouvelé.", "sources": [{"documentId": "mf", "page": 3}]}, {"id": "marketing-concept-127", "chapter": "Diagnostic et stratégie", "question": "Quelle différence y a-t-il entre mesurer les performances et assurer le contrôle marketing ?", "answer": "La mesure constate les résultats. Le contrôle comprend aussi leur comparaison aux objectifs et la mise en place d’actions correctrices pour réduire les écarts.", "sources": [{"documentId": "mf", "page": 4}]}, {"id": "marketing-concept-128", "chapter": "Marketing mix", "question": "Quel rôle joue la marque dans la politique produit ?", "answer": "Elle donne une identité au produit. Le produit et la marque doivent se renforcer mutuellement ; la gestion de marque veille à la cohérence de cette identité.", "sources": [{"documentId": "mf", "page": 4}]}, {"id": "marketing-concept-129", "chapter": "Marketing mix", "question": "Quelle différence y a-t-il entre fonctions techniques et marketing du packaging ?", "answer": "Les fonctions techniques protègent et facilitent l’usage, le transport et le stockage. Les fonctions marketing informent, identifient le produit, expriment son positionnement et favorisent l’achat.", "sources": [{"documentId": "mf", "page": 4}]}, {"id": "marketing-concept-130", "chapter": "Marketing mix", "question": "Comment le packaging contribue-t-il au positionnement ?", "answer": "Il permet de reconnaître et d’identifier le produit et exprime son positionnement par sa présentation et les informations qu’il donne.", "sources": [{"documentId": "mf", "page": 4}]}, {"id": "marketing-concept-131", "chapter": "Marketing mix", "question": "Entre quelles deux limites se situe le prix selon la fiche ?", "answer": "Entre le coût de production et la valeur que le client attribue au produit.", "sources": [{"documentId": "mf", "page": 4}]}, {"id": "marketing-concept-132", "chapter": "Marketing mix", "question": "Pourquoi le positionnement doit-il guider le marketing mix ?", "answer": "Il constitue son facteur de cohérence. Les décisions sur le produit, le prix, la distribution et la communication doivent traduire le même positionnement.", "sources": [{"documentId": "mf", "page": 9}]}, {"id": "marketing-concept-133", "chapter": "Marketing mix", "question": "Pourquoi tenir compte des trois dimensions du produit ?", "answer": "Les consommateurs peuvent être sensibles à ses caractéristiques techniques, commerciales et psychologiques. L’entreprise doit donc réfléchir à ces trois niveaux.", "sources": [{"documentId": "mf", "page": 4}]}, {"id": "marketing-concept-134", "chapter": "Segmentation", "question": "Quels sont les principaux intérêts de la segmentation ?", "answer": "Réduire la complexité du marché, former des groupes homogènes, adapter l’offre, se différencier et repérer des opportunités ou des besoins non satisfaits.", "sources": [{"documentId": "mf", "page": 6}]}, {"id": "marketing-concept-135", "chapter": "Segmentation", "question": "Pourquoi une entreprise doit-elle hiérarchiser les segments ?", "answer": "Elle ne peut pas répondre à tous les besoins de tous les clients. Elle choisit donc où concentrer ses efforts et renonce à certains segments pour mieux en servir d’autres.", "sources": [{"documentId": "mf", "page": 6}]}, {"id": "marketing-concept-136", "chapter": "Segmentation", "question": "Pourquoi n’existe-t-il pas une seule segmentation pertinente ?", "answer": "Une entreprise peut utiliser plusieurs segmentations en même temps. Regrouper les consommateurs ou les produits selon différents critères apporte des éclairages complémentaires.", "sources": [{"documentId": "mf", "page": 6}]}, {"id": "marketing-concept-137", "chapter": "Segmentation", "question": "Que signifie un segment mesurable ?", "answer": "On peut quantifier les individus qui le composent et obtenir des données quantitatives et qualitatives sur ce groupe.", "sources": [{"documentId": "mf", "page": 7}]}, {"id": "marketing-concept-138", "chapter": "Segmentation", "question": "Que signifie un segment accessible ?", "answer": "L’entreprise peut atteindre les personnes du segment par des moyens adaptés, comme un média ou un point de vente.", "sources": [{"documentId": "mf", "page": 7}]}, {"id": "marketing-concept-139", "chapter": "Segmentation", "question": "Que signifie un segment substantiel ?", "answer": "Sa taille est suffisante pour justifier des investissements rentables.", "sources": [{"documentId": "mf", "page": 7}]}, {"id": "marketing-concept-140", "chapter": "Segmentation", "question": "Que signifie un segment différenciable ?", "answer": "Il est distinct des autres segments et réagit différemment aux actions marketing.", "sources": [{"documentId": "mf", "page": 7}]}, {"id": "marketing-concept-141", "chapter": "Segmentation", "question": "Que signifie un segment pertinent ?", "answer": "L’entreprise peut élaborer une stratégie efficace pour ce segment et y disposer d’une possibilité de réussite.", "sources": [{"documentId": "mf", "page": 7}]}, {"id": "marketing-concept-142", "chapter": "Segmentation", "question": "Pourquoi un segment doit-il être actualisable ?", "answer": "La segmentation peut vieillir et devenir obsolète. Les données doivent pouvoir être mises à jour pour suivre les évolutions du marché.", "sources": [{"documentId": "mf", "page": 7}]}, {"id": "marketing-concept-143", "chapter": "Segmentation", "question": "Quelle différence y a-t-il entre sur-segmentation et sous-segmentation ?", "answer": "La sur-segmentation crée trop de petits segments, au risque de rendre les investissements peu rentables. La sous-segmentation ne retient que de très gros segments et distingue insuffisamment les groupes.", "sources": [{"documentId": "mf", "page": 7}]}, {"id": "marketing-concept-144", "chapter": "Segmentation", "question": "Dans quelles situations la segmentation descendante est-elle adaptée ?", "answer": "Lorsque l’on utilise un nombre restreint de critères définis à l’avance, sur des marchés mûrs et pour des problématiques déjà maîtrisées.", "sources": [{"documentId": "mf", "page": 7}]}, {"id": "marketing-concept-145", "chapter": "Segmentation", "question": "Quelle est la principale limite de la segmentation typologique ?", "answer": "Les frontières entre les types peuvent être floues, même si l’analyse cherche à regrouper les individus semblables et à distinguer les groupes.", "sources": [{"documentId": "mf", "page": 8}]}, {"id": "marketing-concept-146", "chapter": "Segmentation", "question": "Que décrit le centre de gravité d’un type dans la segmentation ascendante ?", "answer": "Le profil moyen de ce type, obtenu à partir de la moyenne des variables étudiées.", "sources": [{"documentId": "mf", "page": 8}]}, {"id": "marketing-concept-147", "chapter": "Ciblage", "question": "Pourquoi le ciblage est-il une décision stratégique ?", "answer": "Le choix des segments prioritaires détermine d’autres choix stratégiques, comme le positionnement, et des choix opérationnels, comme le marketing mix.", "sources": [{"documentId": "mf", "page": 8}]}, {"id": "marketing-concept-148", "chapter": "Ciblage", "question": "Quels indicateurs servent à évaluer l’attractivité d’un segment ?", "answer": "Sa taille en valeur et en volume, sa croissance, l’intensité concurrentielle, son accessibilité, sa rentabilité et ses perspectives de développement.", "sources": [{"documentId": "mf", "page": 8}]}, {"id": "marketing-concept-149", "chapter": "Ciblage", "question": "Pourquoi la taille d’un segment ne suffit-elle pas à juger son intérêt ?", "answer": "Un petit segment peut être très rentable. Un grand segment peut être difficile d’accès ou subir une concurrence intense. Il faut combiner plusieurs critères.", "sources": [{"documentId": "mf", "page": 8}]}, {"id": "marketing-concept-150", "chapter": "Ciblage", "question": "Quelles familles de moyens faut-il examiner avant de choisir une cible ?", "answer": "Les moyens financiers, technologiques, humains et organisationnels, ainsi que les moyens informationnels. Le segment choisi doit être compatible avec les capacités de l’entreprise.", "sources": [{"documentId": "mf", "page": 8}]}, {"id": "marketing-concept-151", "chapter": "Ciblage", "question": "Pourquoi le ciblage doit-il être compatible avec la stratégie générale de l’entreprise ?", "answer": "Les segments retenus doivent correspondre à la mission de l’entreprise, à son business model et à ses orientations concurrentielles.", "sources": [{"documentId": "mf", "page": 8}]}, {"id": "marketing-concept-152", "chapter": "Ciblage", "question": "Qu’est-ce que le business model dans l’analyse du ciblage ?", "answer": "La manière dont l’entreprise crée de la valeur et la répartit entre elle-même et ses clients.", "sources": [{"documentId": "mf", "page": 8}]}, {"id": "marketing-concept-153", "chapter": "Ciblage", "question": "Quelle différence y a-t-il entre couverture globale et spécialisation sélective ?", "answer": "La couverture globale vise tous les segments avec une offre large adaptée à chacun. La spécialisation sélective retient certains segments avec des gammes distinctes et une offre concentrée.", "sources": [{"documentId": "mf", "page": 8}]}, {"id": "marketing-concept-154", "chapter": "Ciblage", "question": "Quelle différence y a-t-il entre offre large et offre concentrée sur un seul segment ?", "answer": "Dans les deux cas, un seul segment est visé. Une offre large propose plusieurs possibilités à ce segment ; une offre concentrée se limite à une seule gamme.", "sources": [{"documentId": "mf", "page": 8}]}, {"id": "marketing-concept-155", "chapter": "Ciblage", "question": "Comment la RSE peut-elle influencer le choix des segments ?", "answer": "La politique de responsabilité sociale peut conduire l’entreprise à favoriser certains segments ou à en exclure d’autres.", "sources": [{"documentId": "mf", "page": 8}]}, {"id": "marketing-concept-156", "chapter": "Ciblage", "question": "Quelle difficulté économique le marketing individualisé peut-il poser ?", "answer": "La rentabilité : personnaliser l’offre, parfois jusqu’au sur-mesure, doit rester économiquement viable.", "sources": [{"documentId": "mf", "page": 9}]}, {"id": "marketing-concept-157", "chapter": "Positionnement", "question": "Quels sont les quatre grands thèmes d’un positionnement ?", "answer": "Les performances du produit, l’imaginaire de marque, les publics cibles et le mode d’utilisation.", "sources": [{"documentId": "mf", "page": 9}]}, {"id": "marketing-concept-158", "chapter": "Positionnement", "question": "Pourquoi le consommateur doit-il identifier clairement la catégorie du produit ?", "answer": "Il doit comprendre immédiatement de quel produit il s’agit, dans quel univers il se situe et à quels bénéfices il peut le rattacher. Une définition floue brouille sa perception.", "sources": [{"documentId": "mf", "page": 9}]}, {"id": "marketing-concept-159", "chapter": "Positionnement", "question": "Sur quels éléments peut reposer la différenciation d’un produit ?", "answer": "Ses attributs et son efficacité, les services associés, les circuits de distribution, la force de vente, l’image, la clientèle visée ou le mode de consommation.", "sources": [{"documentId": "mf", "page": 10}]}, {"id": "marketing-concept-160", "chapter": "Positionnement", "question": "Qu’est-ce qu’un positionnement crédible ?", "answer": "Un positionnement dont les promesses sont jugées réalisables par les consommateurs : ils croient que le produit les tiendra.", "sources": [{"documentId": "mf", "page": 9}]}, {"id": "marketing-concept-161", "chapter": "Positionnement", "question": "Pourquoi un positionnement doit-il être simple et durable ?", "answer": "Il doit être facile à comprendre, avec peu de caractéristiques et une formulation courte. Il engage l’entreprise dans le temps tout en restant pertinent face aux évolutions du marché.", "sources": [{"documentId": "mf", "page": 9}]}, {"id": "marketing-concept-162", "chapter": "Positionnement", "question": "Comment repérer un écart entre positionnement souhaité et positionnement perçu ?", "answer": "Comparer ce que l’entreprise cherche à exprimer dans ses actions marketing avec la perception réelle des consommateurs, mesurée régulièrement.", "sources": [{"documentId": "mf", "page": 9}]}, {"id": "marketing-concept-163", "chapter": "Positionnement", "question": "Comment choisir plusieurs bénéfices de positionnement ?", "answer": "Examiner leur importance pour la cible, leur caractère distinctif, leur supériorité, leur facilité à être communiqués, leur caractère défendable et justifiable, ainsi que leur rentabilité.", "sources": [{"documentId": "mf", "page": 9}]}, {"id": "marketing-concept-164", "chapter": "Positionnement", "question": "Qu’est-ce que la stratégie d’imitation dite « me-too » ?", "answer": "Elle consiste à copier le positionnement d’un concurrent, à l’opposé d’une stratégie de différenciation.", "sources": [{"documentId": "mf", "page": 10}]}], "documents": ["mf"], "legacyCardIds": ["marketing-concept-001", "marketing-concept-002", "marketing-concept-003", "marketing-concept-004", "marketing-concept-005", "marketing-concept-006", "marketing-concept-007", "marketing-concept-008", "marketing-concept-009", "marketing-concept-010", "marketing-concept-011", "marketing-concept-012", "marketing-concept-013", "marketing-concept-014", "marketing-concept-015", "marketing-concept-016", "marketing-concept-017", "marketing-concept-018", "marketing-concept-019", "marketing-concept-020", "marketing-concept-021", "marketing-concept-022", "marketing-concept-023", "marketing-concept-024", "marketing-concept-025", "marketing-concept-026", "marketing-concept-027", "marketing-concept-028", "marketing-concept-029", "marketing-concept-030", "marketing-concept-031", "marketing-concept-032", "marketing-concept-033", "marketing-concept-034", "marketing-concept-035", "marketing-concept-036", "marketing-concept-037", "marketing-concept-038", "marketing-concept-039", "marketing-concept-040", "marketing-concept-041", "marketing-concept-042", "marketing-concept-043", "marketing-concept-044", "marketing-concept-045", "marketing-concept-046", "marketing-concept-047", "marketing-concept-048", "marketing-concept-049", "marketing-concept-050", "marketing-concept-051", "marketing-concept-052", "marketing-concept-053", "marketing-concept-054", "marketing-concept-055", "marketing-concept-056", "marketing-concept-057", "marketing-concept-058", "marketing-concept-059", "marketing-concept-060", "marketing-concept-061", "marketing-concept-062", "marketing-concept-063", "marketing-concept-064", "marketing-concept-065", "marketing-concept-066", "marketing-concept-067", "marketing-concept-068", "marketing-concept-069", "marketing-concept-070", "marketing-concept-071", "marketing-concept-072", "marketing-concept-073", "marketing-concept-074", "marketing-concept-075", "marketing-concept-076", "marketing-concept-077", "marketing-concept-078", "marketing-concept-079", "marketing-concept-080", "marketing-concept-081", "marketing-concept-082", "marketing-concept-083", "marketing-concept-084", "marketing-concept-085", "marketing-concept-086", "marketing-concept-087", "marketing-concept-088", "marketing-concept-089", "marketing-concept-090", "marketing-concept-091", "marketing-concept-092", "marketing-concept-093", "marketing-concept-094", "marketing-concept-095", "marketing-concept-096", "marketing-concept-097", "marketing-concept-098", "marketing-concept-099", "marketing-concept-100", "marketing-concept-101", "marketing-concept-102", "marketing-concept-103", "marketing-concept-104"], "subjectId": "marketing", "subjectTitle": "Marketing", "quizTitle": "Tout le cours", "variant": "complete"}, {"subjectId": "marketing", "subjectTitle": "Marketing", "symbol": "M", "documents": ["mf"], "id": "marketing-essentiel", "title": "Marketing · L’essentiel", "quizTitle": "L’essentiel", "variant": "essential", "description": "Définitions, mémos et repères clés de ta fiche : marché, SWOT, mix, segmentation, ciblage et positionnement.", "storageKey": "declic-marketing-essentiel-v1", "cards": [{"id": "marketing-concept-001", "chapter": "Bases du marketing", "question": "Quelle est la définition du marketing ?", "answer": "Le marketing regroupe les activités qui permettent de comprendre les besoins et désirs, de concevoir une offre adaptée et de créer, communiquer et délivrer de la valeur. Il vise des relations durables avec les clients.", "sources": [{"documentId": "mf", "page": 1}]}, {"id": "marketing-concept-048", "chapter": "Marché", "question": "Comment calcule-t-on une part de marché absolue ?", "answer": "Part de marché (%) = ventes de l’entreprise / ventes totales du marché × 100. Le calcul peut se faire en volume ou en valeur.", "sources": [{"documentId": "mf", "page": 2}]}, {"id": "marketing-concept-049", "chapter": "Marché", "question": "Comment calcule-t-on une part de marché relative ?", "answer": "Part de marché relative = part de marché de l’entreprise / part de marché de son principal concurrent. C’est un ratio.", "sources": [{"documentId": "mf", "page": 2}]}, {"id": "marketing-concept-050", "chapter": "Marché", "question": "Comment interprète-t-on une part de marché relative ?", "answer": "Supérieure à 1 : l’entreprise dépasse son principal concurrent. Égale à 1 : elles réalisent les mêmes ventes. Inférieure à 1 : l’entreprise est derrière.", "sources": [{"documentId": "mf", "page": 2}]}, {"id": "marketing-concept-051", "chapter": "Marché", "question": "Comment calcule-t-on le taux de pénétration ?", "answer": "Taux de pénétration (%) = marché réel / marché potentiel × 100.", "sources": [{"documentId": "mf", "page": 2}]}, {"id": "marketing-concept-052", "chapter": "Marché", "question": "Quelles sont les quatre phases du cycle de vie d’un marché ?", "answer": "Naissance, croissance, maturité et déclin.", "sources": [{"documentId": "mf", "page": 2}]}, {"id": "marketing-concept-053", "chapter": "Diagnostic et stratégie", "question": "Qu’est-ce qu’une analyse interne ?", "answer": "C’est l’analyse des ressources, compétences, fonctionnement et politique marketing de l’organisation pour identifier ses forces et ses faiblesses.", "sources": [{"documentId": "mf", "page": 2}]}, {"id": "marketing-concept-054", "chapter": "Diagnostic et stratégie", "question": "À quoi sert la chaîne de valeur de Porter ?", "answer": "Elle identifie les activités qui créent de la valeur et permet d’en analyser les coûts.", "sources": [{"documentId": "mf", "page": 2}]}, {"id": "marketing-concept-056", "chapter": "Diagnostic et stratégie", "question": "Quelle différence y a-t-il entre notoriété spontanée, top of mind et notoriété assistée ?", "answer": "Spontanée : la marque est citée sans aide. Top of mind : elle est citée en premier. Assistée : elle est reconnue à partir d’une liste.", "sources": [{"documentId": "mf", "page": 3}]}, {"id": "marketing-concept-059", "chapter": "Diagnostic et stratégie", "question": "Que signifie SWOT ?", "answer": "Strengths, Weaknesses, Opportunities, Threats : forces, faiblesses, opportunités et menaces.", "sources": [{"documentId": "mf", "page": 3}]}, {"id": "marketing-concept-060", "chapter": "Diagnostic et stratégie", "question": "Quelle différence y a-t-il entre les éléments internes et externes du SWOT ?", "answer": "Les forces et faiblesses sont internes à l’organisation. Les opportunités et menaces viennent de l’environnement externe.", "sources": [{"documentId": "mf", "page": 3}]}, {"id": "marketing-concept-061", "chapter": "Diagnostic et stratégie", "question": "Quelles sont les quatre fonctions du pilotage marketing ?", "answer": "Analyse, planification, implémentation et contrôle. La démarche est itérative.", "sources": [{"documentId": "mf", "page": 3}]}, {"id": "marketing-concept-063", "chapter": "Diagnostic et stratégie", "question": "Quelles sont les trois étapes du contrôle marketing ?", "answer": "Mesurer les performances, comparer les résultats aux objectifs, puis mettre en place des actions correctrices.", "sources": [{"documentId": "mf", "page": 4}]}, {"id": "marketing-concept-064", "chapter": "Diagnostic et stratégie", "question": "Quelles sont les quatre stratégies de croissance d’Ansoff ?", "answer": "Pénétration de marché : produits et marchés existants. Développement de marché : produits existants et nouveaux marchés. Développement de produits : nouveaux produits et marchés existants. Diversification : nouveaux produits et nouveaux marchés.", "sources": [{"documentId": "mf", "page": 4}]}, {"id": "marketing-concept-065", "chapter": "Marketing mix", "question": "Qu’est-ce que le marketing mix ?", "answer": "C’est l’ensemble cohérent des outils dont dispose l’entreprise pour atteindre ses objectifs sur le marché visé.", "sources": [{"documentId": "mf", "page": 4}]}, {"id": "marketing-concept-066", "chapter": "Marketing mix", "question": "Quels sont les 4P ?", "answer": "Product : produit. Price : prix. Place : distribution. Promotion : communication.", "sources": [{"documentId": "mf", "page": 3}]}, {"id": "marketing-concept-067", "chapter": "Marketing mix", "question": "Quelles sont les trois dimensions du produit ?", "answer": "Les caractéristiques techniques, commerciales et psychologiques.", "sources": [{"documentId": "mf", "page": 4}]}, {"id": "marketing-concept-070", "chapter": "Marketing mix", "question": "Quelles sont les fonctions du packaging ?", "answer": "Fonctions techniques : protéger, conserver et faciliter l’utilisation, le transport et le stockage. Fonctions marketing : informer, identifier le produit, exprimer le positionnement et favoriser l’achat.", "sources": [{"documentId": "mf", "page": 4}]}, {"id": "marketing-concept-081", "chapter": "Segmentation", "question": "Quelle est la définition de la segmentation ?", "answer": "La segmentation consiste à découper un marché en groupes de consommateurs qui partagent des besoins, caractéristiques ou comportements communs.", "sources": [{"documentId": "mf", "page": 5}]}, {"id": "marketing-concept-082", "chapter": "Segmentation", "question": "Quels sont les principaux critères de segmentation ?", "answer": "Critères géographiques, sociodémographiques, psychographiques, avantages recherchés, comportements et caractéristiques physiques.", "sources": [{"documentId": "mf", "page": 5}]}, {"id": "marketing-concept-086", "chapter": "Segmentation", "question": "Qu’est-ce que la segmentation multicritère ?", "answer": "Elle combine plusieurs critères pour former des segments plus précis et plus homogènes, mais généralement plus petits.", "sources": [{"documentId": "mf", "page": 5}]}, {"id": "marketing-concept-087", "chapter": "Segmentation", "question": "Quelles sont les qualités d’un segment utile ?", "answer": "Un segment doit être différenciable, mesurable, accessible, substantiel, pertinent et actualisable. Il réunit des consommateurs aux caractéristiques homogènes.", "sources": [{"documentId": "mf", "page": 7}]}, {"id": "marketing-concept-088", "chapter": "Segmentation", "question": "Quelle différence y a-t-il entre segmentation de l’offre et de la demande ?", "answer": "La segmentation de l’offre regroupe les produits et services. La segmentation de la demande regroupe les consommateurs ou les entreprises clientes.", "sources": [{"documentId": "mf", "page": 6}]}, {"id": "marketing-concept-089", "chapter": "Segmentation", "question": "Qu’est-ce que la segmentation descendante ?", "answer": "Elle découpe successivement la population selon des critères choisis à l’avance. On l’appelle aussi segmentation a priori.", "sources": [{"documentId": "mf", "page": 7}]}, {"id": "marketing-concept-090", "chapter": "Segmentation", "question": "Qu’est-ce que la segmentation ascendante ?", "answer": "Elle regroupe les individus selon leurs ressemblances à partir de nombreuses données. On l’appelle aussi segmentation typologique.", "sources": [{"documentId": "mf", "page": 8}]}, {"id": "marketing-concept-091", "chapter": "Segmentation", "question": "Quels critères permettent de segmenter un marché B2B ?", "answer": "Le secteur d’activité, la taille, les performances économiques, la localisation, le processus de décision, les critères de choix des fournisseurs et la fidélité.", "sources": [{"documentId": "mf", "page": 7}]}, {"id": "marketing-concept-092", "chapter": "Ciblage", "question": "Quelle est la définition du ciblage ?", "answer": "Le ciblage consiste à évaluer les segments puis à choisir celui ou ceux sur lesquels l’entreprise concentrera ses efforts.", "sources": [{"documentId": "mf", "page": 5}]}, {"id": "marketing-concept-093", "chapter": "Ciblage", "question": "Sur quels critères choisit-on une cible ?", "answer": "On évalue l’attractivité du segment et sa compatibilité avec les objectifs, ressources et compétences de l’entreprise.", "sources": [{"documentId": "mf", "page": 8}]}, {"id": "marketing-concept-094", "chapter": "Ciblage", "question": "Qu’est-ce que le ciblage indifférencié ?", "answer": "Il consiste à proposer une offre commune à l’ensemble du marché, en privilégiant les besoins partagés.", "sources": [{"documentId": "mf", "page": 5}]}, {"id": "marketing-concept-095", "chapter": "Ciblage", "question": "Qu’est-ce que le ciblage différencié ?", "answer": "Il consiste à servir plusieurs segments avec une offre et un marketing mix adaptés à chacun.", "sources": [{"documentId": "mf", "page": 5}]}, {"id": "marketing-concept-096", "chapter": "Ciblage", "question": "Qu’est-ce que le ciblage concentré ?", "answer": "Il consiste à concentrer les efforts sur un segment particulier. Une niche est un segment particulièrement étroit et spécifique.", "sources": [{"documentId": "mf", "page": 9}]}, {"id": "marketing-concept-097", "chapter": "Ciblage", "question": "Qu’est-ce que le marketing individualisé ?", "answer": "C’est l’adaptation de tout ou partie de l’offre à chaque individu. On l’appelle aussi marketing one to one.", "sources": [{"documentId": "mf", "page": 9}]}, {"id": "marketing-concept-099", "chapter": "Positionnement", "question": "Quelle est la définition du positionnement ?", "answer": "Le positionnement vise à donner à l’offre une place claire et distinctive dans l’esprit des clients ciblés, par rapport aux concurrents.", "sources": [{"documentId": "mf", "page": 9}]}, {"id": "marketing-concept-100", "chapter": "Positionnement", "question": "Quelles sont les deux composantes du positionnement ?", "answer": "L’identification, qui rattache l’offre à une catégorie, et la différenciation, qui la distingue des offres concurrentes.", "sources": [{"documentId": "mf", "page": 6}]}, {"id": "marketing-concept-102", "chapter": "Positionnement", "question": "Comment formule-t-on un énoncé de positionnement ?", "answer": "« Pour [cible], la marque X est [catégorie] qui apporte [bénéfice distinctif]. »", "sources": [{"documentId": "mf", "page": 6}]}, {"id": "marketing-concept-103", "chapter": "Positionnement", "question": "Quels sont les critères d’un bon positionnement ?", "answer": "Il doit être attractif, différenciant, crédible, simple, profitable et pérenne.", "sources": [{"documentId": "mf", "page": 9}]}, {"id": "marketing-concept-104", "chapter": "Positionnement", "question": "Que signifie USP ?", "answer": "Unique Selling Proposition : une proposition de vente unique qui met en avant un bénéfice principal et distinctif.", "sources": [{"documentId": "mf", "page": 9}]}, {"id": "marketing-concept-105", "chapter": "Bases du marketing", "question": "Quels sont les principaux objectifs du marketing ?", "answer": "Attirer de nouveaux clients, conserver les clients existants, satisfaire leurs besoins et créer de la valeur pour construire des relations durables et rentables.", "sources": [{"documentId": "mf", "page": 1}]}, {"id": "marketing-concept-106", "chapter": "Démarche et orientations", "question": "Quelles sont les quatre actions de la démarche marketing présentées dans la fiche ?", "answer": "Étudier le marché et les besoins, repérer la concurrence, définir les objectifs, puis déterminer les moyens d’action pour les atteindre.", "sources": [{"documentId": "mf", "page": 1}]}, {"id": "marketing-concept-109", "chapter": "Bases du marketing", "question": "Comment le marketing crée-t-il de la valeur pour les clients et pour l’organisation ?", "answer": "L’organisation conçoit une offre adaptée aux besoins des clients et construit avec eux des relations rentables. Les clients obtiennent de la valeur, et l’organisation en reçoit en retour.", "sources": [{"documentId": "mf", "page": 1}]}, {"id": "marketing-concept-131", "chapter": "Marketing mix", "question": "Entre quelles deux limites se situe le prix selon la fiche ?", "answer": "Entre le coût de production et la valeur que le client attribue au produit.", "sources": [{"documentId": "mf", "page": 4}]}]}, {"id": "communication", "title": "Communication commerciale", "description": "130 questions pour réviser toutes les notions du cours.", "symbol": "C", "storageKey": "declic-communication-concepts-v3", "cards": [{"id": "communication-concept-001", "chapter": "1 · Les fondamentaux", "question": "Quelle est la définition de la communication d’une entreprise ?", "answer": "C’est l’ensemble des informations, messages et signaux qu’une entreprise émet, volontairement ou non, vers tous ses publics.", "sources": [{"documentId": "com", "page": 1}]}, {"id": "communication-concept-002", "chapter": "1 · Les fondamentaux", "question": "Quelle est la définition de la communication commerciale ?", "answer": "C’est l’ensemble des actions visant à influencer positivement les attitudes et comportements des publics dans une perspective de performance économique.", "sources": [{"documentId": "com", "page": 1}]}, {"id": "communication-concept-003", "chapter": "1 · Les fondamentaux", "question": "Quelles sont les quatre fonctions de la communication commerciale ?", "answer": "Informer, séduire, convaincre et fidéliser.", "sources": [{"documentId": "com", "page": 1}]}, {"id": "communication-concept-004", "chapter": "1 · Les fondamentaux", "question": "Quelle différence y a-t-il entre objectifs économiques et symboliques de communication ?", "answer": "Les objectifs économiques concernent notamment les ventes, les parts de marché et la fidélisation. Les objectifs symboliques concernent l’image, la notoriété et la crédibilité.", "sources": [{"documentId": "com", "page": 1}]}, {"id": "communication-concept-005", "chapter": "1 · Les fondamentaux", "question": "Qu’est-ce que la communication institutionnelle ?", "answer": "C’est la communication qui porte sur l’entreprise dans son ensemble.", "sources": [{"documentId": "com", "page": 1}]}, {"id": "communication-concept-006", "chapter": "1 · Les fondamentaux", "question": "Qu’est-ce que la communication de produit ?", "answer": "Elle fait connaître le produit et ses caractéristiques, en restant cohérente avec l’image de marque.", "sources": [{"documentId": "com", "page": 2}]}, {"id": "communication-concept-007", "chapter": "1 · Les fondamentaux", "question": "Qu’est-ce que la communication de marque ?", "answer": "Elle construit un territoire de marque distinctif et favorise la différenciation et la fidélisation.", "sources": [{"documentId": "com", "page": 2}]}, {"id": "communication-concept-008", "chapter": "1 · Les fondamentaux", "question": "Qu’est-ce qu’un annonceur ?", "answer": "C’est l’entreprise qui commande une campagne de communication.", "sources": [{"documentId": "com", "page": 2}]}, {"id": "communication-concept-009", "chapter": "1 · Les fondamentaux", "question": "Quel est le rôle d’une agence de communication ?", "answer": "Elle conçoit les campagnes de communication.", "sources": [{"documentId": "com", "page": 2}]}, {"id": "communication-concept-010", "chapter": "1 · Les fondamentaux", "question": "Qu’est-ce qu’une régie publicitaire ?", "answer": "C’est un intermédiaire qui commercialise les espaces publicitaires des médias auprès des annonceurs et des agences.", "sources": [{"documentId": "com", "page": 5}]}, {"id": "communication-concept-011", "chapter": "1 · Les fondamentaux", "question": "Qu’est-ce que la saturation publicitaire ?", "answer": "C’est la surabondance de messages publicitaires reçus par le public. Elle peut entraîner une fatigue et une moindre attention aux publicités.", "sources": [{"documentId": "com", "page": 2}]}, {"id": "communication-concept-012", "chapter": "1 · Les fondamentaux", "question": "Qu’est-ce que la fragmentation des audiences ?", "answer": "C’est la dispersion des publics entre de nombreux médias et supports.", "sources": [{"documentId": "com", "page": 2}]}, {"id": "communication-concept-013", "chapter": "2 · La stratégie", "question": "Quelle est la définition d’une stratégie de communication ?", "answer": "C’est l’ensemble des choix et orientations qui guident les actions de communication pour atteindre des objectifs précis auprès de cibles identifiées.", "sources": [{"documentId": "com", "page": 3}]}, {"id": "communication-concept-014", "chapter": "2 · La stratégie", "question": "Quelles sont les quatre étapes d’une stratégie de communication ?", "answer": "Diagnostic, objectifs de communication, cibles, puis positionnement et message ou stratégie créative.", "sources": [{"documentId": "com", "page": 6}]}, {"id": "communication-concept-015", "chapter": "2 · La stratégie", "question": "Qu’est-ce qu’un audit de communication ?", "answer": "C’est l’analyse approfondie de la situation de communication de l’organisation. Le diagnostic est notamment synthétisé dans une matrice SWOT.", "sources": [{"documentId": "com", "page": 6}]}, {"id": "communication-concept-016", "chapter": "2 · La stratégie", "question": "Quels sont les trois objectifs de communication ?", "answer": "Cognitif : faire savoir ou connaître. Affectif : faire aimer. Conatif : faire agir.", "sources": [{"documentId": "com", "page": 6}]}, {"id": "communication-concept-017", "chapter": "2 · La stratégie", "question": "Que signifie SMART pour un objectif ?", "answer": "Spécifique, mesurable, atteignable, réaliste et temporel.", "sources": [{"documentId": "com", "page": 3}]}, {"id": "communication-concept-018", "chapter": "2 · La stratégie", "question": "Quelle différence y a-t-il entre cible marketing et cible de communication ?", "answer": "La cible marketing désigne les personnes à qui l’entreprise vend. La cible de communication désigne les personnes à qui elle s’adresse.", "sources": [{"documentId": "com", "page": 6}]}, {"id": "communication-concept-019", "chapter": "2 · La stratégie", "question": "Qu’est-ce que la cible principale ?", "answer": "Ce sont les personnes directement concernées par le produit ou le service.", "sources": [{"documentId": "com", "page": 6}]}, {"id": "communication-concept-020", "chapter": "2 · La stratégie", "question": "Qu’est-ce que le cœur de cible ?", "answer": "C’est le sous-ensemble prioritaire de la cible principale.", "sources": [{"documentId": "com", "page": 4}]}, {"id": "communication-concept-021", "chapter": "2 · La stratégie", "question": "Qu’est-ce qu’une cible secondaire ?", "answer": "C’est un public qui peut recommander, relayer ou influencer l’achat sans être la cible principale.", "sources": [{"documentId": "com", "page": 4}]}, {"id": "communication-concept-022", "chapter": "2 · La stratégie", "question": "Qu’est-ce qu’un insight consommateur ?", "answer": "C’est la perception d’un problème ou d’un dilemme non résolu dans une catégorie de produits. Il révèle une motivation, un besoin ou un manque.", "sources": [{"documentId": "com", "page": 6}]}, {"id": "communication-concept-023", "chapter": "2 · La stratégie", "question": "Quelles sont les trois grandes motivations du consommateur ?", "answer": "Hédonistes : se faire plaisir. Oblatives : faire plaisir aux autres. Auto-expression : exprimer sa personnalité ou l’image de soi.", "sources": [{"documentId": "com", "page": 6}]}, {"id": "communication-concept-024", "chapter": "2 · La stratégie", "question": "Quels sont les principaux freins à l’achat ?", "answer": "Les peurs, les inhibitions et les risques perçus.", "sources": [{"documentId": "com", "page": 6}]}, {"id": "communication-concept-025", "chapter": "2 · La stratégie", "question": "Quelle est la définition du positionnement ?", "answer": "C’est l’ensemble des traits saillants qui permettent au consommateur d’identifier l’offre et de la différencier de ses concurrents.", "sources": [{"documentId": "com", "page": 6}]}, {"id": "communication-concept-026", "chapter": "2 · La stratégie", "question": "Qu’est-ce qu’une copy stratégie ?", "answer": "C’est un brief créatif qui synthétise la réflexion stratégique et fixe ce que le message doit communiquer.", "sources": [{"documentId": "com", "page": 7}]}, {"id": "communication-concept-027", "chapter": "2 · La stratégie", "question": "Quels sont les éléments d’une copy stratégie ?", "answer": "Promesse, bénéfice consommateur, avantage produit, ton, preuves et contraintes.", "sources": [{"documentId": "com", "page": 7}]}, {"id": "communication-concept-028", "chapter": "2 · La stratégie", "question": "Qu’est-ce que la promesse publicitaire ?", "answer": "C’est ce que la marque promet d’apporter au consommateur. Elle doit être unique, simple et ne pas enfermer la création.", "sources": [{"documentId": "com", "page": 7}]}, {"id": "communication-concept-029", "chapter": "2 · La stratégie", "question": "Quelle différence y a-t-il entre bénéfice consommateur et avantage produit ?", "answer": "Le bénéfice est ce que le consommateur retire de l’usage. L’avantage produit est une performance ou caractéristique du produit.", "sources": [{"documentId": "com", "page": 7}]}, {"id": "communication-concept-030", "chapter": "2 · La stratégie", "question": "Qu’est-ce que le ton d’un message publicitaire ?", "answer": "C’est le climat ou l’atmosphère du message : informatif, démonstratif, humoristique, imaginaire ou symbolique, notamment.", "sources": [{"documentId": "com", "page": 7}]}, {"id": "communication-concept-031", "chapter": "2 · La stratégie", "question": "À quoi servent les preuves dans une copy stratégie ?", "answer": "Elles justifient la promesse par des éléments concrets.", "sources": [{"documentId": "com", "page": 7}]}, {"id": "communication-concept-032", "chapter": "2 · La stratégie", "question": "Quelles contraintes encadrent une copy stratégie ?", "answer": "Les contraintes peuvent être légales, temporelles, budgétaires ou liées à la charte graphique.", "sources": [{"documentId": "com", "page": 7}]}, {"id": "communication-concept-033", "chapter": "3 · Les théories", "question": "Quels sont les éléments du modèle de Lasswell ?", "answer": "L’émetteur, le message, la cible, le canal et l’effet. Le modèle se résume par « Qui dit quoi, à qui, par quel canal, avec quel effet ? ».", "sources": [{"documentId": "com", "page": 7}]}, {"id": "communication-concept-034", "chapter": "3 · Les théories", "question": "Quelle est la principale limite du modèle de Shannon et Weaver présenté dans le cours ?", "answer": "C’est un modèle linéaire ou télégraphique qui ne prend pas en compte la rétroaction.", "sources": [{"documentId": "com", "page": 8}]}, {"id": "communication-concept-035", "chapter": "3 · Les théories", "question": "Quelles sont les six fonctions du langage de Jakobson ?", "answer": "Référentielle, expressive, conative, phatique, poétique et métalinguistique.", "sources": [{"documentId": "com", "page": 8}]}, {"id": "communication-concept-036", "chapter": "3 · Les théories", "question": "Qu’est-ce que la rétroaction ?", "answer": "C’est le retour d’information qui permet à un système de connaître son état et de se réguler.", "sources": [{"documentId": "com", "page": 8}]}, {"id": "communication-concept-037", "chapter": "3 · Les théories", "question": "Qu’est-ce que la cybernétique ?", "answer": "C’est la science des communications et de la régulation dans l’être vivant et la machine.", "sources": [{"documentId": "com", "page": 8}]}, {"id": "communication-concept-038", "chapter": "3 · Les théories", "question": "Quel principe fondamental retient-on de l’école de Palo Alto ?", "answer": "On ne peut pas ne pas communiquer : les comportements et le non-verbal transmettent aussi des messages.", "sources": [{"documentId": "com", "page": 8}]}, {"id": "communication-concept-039", "chapter": "3 · Les théories", "question": "Quels sont les deux niveaux d’un message selon Palo Alto ?", "answer": "Le contenu, c’est-à-dire ce qui est dit, et la relation, c’est-à-dire la manière dont c’est dit.", "sources": [{"documentId": "com", "page": 8}]}, {"id": "communication-concept-040", "chapter": "3 · Les théories", "question": "Que signifient logos, pathos et ethos ?", "answer": "Logos : persuasion par la raison et la démonstration. Pathos : persuasion par l’émotion. Ethos : persuasion par le statut et la crédibilité de l’émetteur.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-041", "chapter": "3 · Les théories", "question": "Qu’est-ce que le modèle behavioriste ?", "answer": "Il explique les comportements comme des réponses à des stimuli extérieurs. La répétition et la nature des stimuli favorisent le conditionnement.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-042", "chapter": "3 · Les théories", "question": "Que signifie AIDA ?", "answer": "Attention, intérêt, désir, achat.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-043", "chapter": "3 · Les théories", "question": "Quelles sont les six étapes de la hiérarchie des effets ?", "answer": "Prise de conscience, connaissance, appréciation, préférence, conviction et achat.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-044", "chapter": "3 · Les théories", "question": "Qu’est-ce que le storytelling ?", "answer": "C’est l’art de raconter une histoire pour susciter l’émotion, donner du sens et convaincre.", "sources": [{"documentId": "com", "page": 10}]}, {"id": "communication-concept-045", "chapter": "3 · Les théories", "question": "Qu’est-ce que le two-step flow of communication ?", "answer": "C’est une diffusion de la communication en deux temps, dans laquelle les leaders d’opinion jouent un rôle de relais et d’influence.", "sources": [{"documentId": "com", "page": 10}]}, {"id": "communication-concept-046", "chapter": "3 · Les théories", "question": "Qu’est-ce que la sémiotique ?", "answer": "C’est la science générale des signes.", "sources": [{"documentId": "com", "page": 10}]}, {"id": "communication-concept-047", "chapter": "3 · Les théories", "question": "Quelle différence y a-t-il entre signifiant et signifié ?", "answer": "Le signifiant est la forme perceptible du signe. Le signifié est le sens ou le concept qui lui est associé.", "sources": [{"documentId": "com", "page": 10}]}, {"id": "communication-concept-048", "chapter": "3 · Les théories", "question": "Quelle différence y a-t-il entre dénotation et connotation ?", "answer": "La dénotation correspond au sens directement décrit. La connotation renvoie aux significations et valeurs subjectives associées au signe.", "sources": [{"documentId": "com", "page": 10}]}, {"id": "communication-concept-049", "chapter": "3 · Les théories", "question": "Qu’est-ce qu’un signe polysémique ?", "answer": "C’est un signe qui peut recevoir plusieurs significations ou interprétations.", "sources": [{"documentId": "com", "page": 10}]}, {"id": "communication-concept-050", "chapter": "3 · Les théories", "question": "Qu’est-ce qu’une cascade de propagation ?", "answer": "C’est une diffusion dans laquelle chaque personne transmet l’information à plusieurs autres, qui la retransmettent à leur tour.", "sources": [{"documentId": "com", "page": 4}]}, {"id": "communication-concept-051", "chapter": "3 · Les théories", "question": "Pourquoi une rumeur peut-elle se déformer ?", "answer": "Les préjugés et la culture des personnes qui transmettent l’information peuvent orienter sa sélection, sa transformation et son amplification.", "sources": [{"documentId": "com", "page": 4}]}, {"id": "communication-concept-052", "chapter": "4 · Éthique et réglementation", "question": "Quel est le rôle de l’ARPP ?", "answer": "L’Autorité de régulation professionnelle de la publicité participe à l’autorégulation de la publicité et formule des recommandations.", "sources": [{"documentId": "com", "page": 10}]}, {"id": "communication-concept-053", "chapter": "4 · Éthique et réglementation", "question": "Quel est le rôle de l’ARCOM ?", "answer": "Elle régule les médias audiovisuels.", "sources": [{"documentId": "com", "page": 11}]}, {"id": "communication-concept-054", "chapter": "4 · Éthique et réglementation", "question": "Quel est le rôle de la CNIL ?", "answer": "Elle veille à la protection des données personnelles et encadre leur collecte et leur utilisation.", "sources": [{"documentId": "com", "page": 11}]}, {"id": "communication-concept-055", "chapter": "4 · Éthique et réglementation", "question": "Quel est le rôle de la DGCCRF ?", "answer": "Elle lutte notamment contre les pratiques commerciales trompeuses.", "sources": [{"documentId": "com", "page": 11}]}, {"id": "communication-concept-056", "chapter": "4 · Éthique et réglementation", "question": "Qu’est-ce qu’une publicité trompeuse ?", "answer": "C’est une publicité qui induit le consommateur en erreur, notamment sur le prix, la qualité ou les caractéristiques de l’offre.", "sources": [{"documentId": "com", "page": 11}]}, {"id": "communication-concept-057", "chapter": "4 · Éthique et réglementation", "question": "Qu’est-ce qu’une publicité comparative ?", "answer": "C’est une publicité qui identifie explicitement ou implicitement un concurrent ou les biens et services qu’il propose.", "sources": [{"documentId": "com", "page": 11}]}, {"id": "communication-concept-058", "chapter": "4 · Éthique et réglementation", "question": "Que signifie RGPD ?", "answer": "Règlement général sur la protection des données. Il encadre la protection des données personnelles.", "sources": [{"documentId": "com", "page": 11}]}, {"id": "communication-concept-059", "chapter": "4 · Éthique et réglementation", "question": "Qu’est-ce que la communication éthique ?", "answer": "C’est une communication responsable qui tient compte de ses effets et respecte les publics auxquels elle s’adresse.", "sources": [{"documentId": "com", "page": 12}]}, {"id": "communication-concept-060", "chapter": "5 · L’image de marque", "question": "Quelle différence y a-t-il entre identité, image et réputation de marque ?", "answer": "L’identité est ce que la marque veut exprimer. L’image est la représentation que les publics se font d’elle. La réputation se construit dans la durée à partir des opinions et expériences.", "sources": [{"documentId": "com", "page": 13}]}, {"id": "communication-concept-061", "chapter": "5 · L’image de marque", "question": "Qu’est-ce que la personnalité de marque ?", "answer": "C’est l’ensemble des caractéristiques humaines associées à une marque.", "sources": [{"documentId": "com", "page": 13}]}, {"id": "communication-concept-062", "chapter": "5 · L’image de marque", "question": "Quelles sont les cinq dimensions de la personnalité de marque selon Aaker ?", "answer": "Sincérité, excitation, compétence, sophistication et robustesse.", "sources": [{"documentId": "com", "page": 13}]}, {"id": "communication-concept-063", "chapter": "5 · L’image de marque", "question": "Qu’est-ce que le capital marque selon Keller ?", "answer": "C’est la valeur liée à ce que les consommateurs pensent, ressentent et croient au sujet de la marque, au-delà de la qualité réelle du produit.", "sources": [{"documentId": "com", "page": 14}]}, {"id": "communication-concept-064", "chapter": "5 · L’image de marque", "question": "Quels sont les quatre niveaux de la pyramide de Keller ?", "answer": "Notoriété, associations, réponse et résonance.", "sources": [{"documentId": "com", "page": 14}]}, {"id": "communication-concept-065", "chapter": "5 · L’image de marque", "question": "Quelles sont les deux grandes catégories d’associations à la marque ?", "answer": "Les associations de performance, liées aux qualités fonctionnelles, et les associations symboliques, liées aux valeurs, au style de vie et à la personnalité.", "sources": [{"documentId": "com", "page": 14}]}, {"id": "communication-concept-066", "chapter": "5 · L’image de marque", "question": "Quelle différence y a-t-il entre jugements et sentiments envers une marque ?", "answer": "Les jugements sont des évaluations rationnelles, notamment de qualité et de crédibilité. Les sentiments sont les réactions affectives suscitées par la marque.", "sources": [{"documentId": "com", "page": 14}]}, {"id": "communication-concept-067", "chapter": "5 · L’image de marque", "question": "Qu’est-ce que la résonance de marque ?", "answer": "C’est une relation forte et durable avec la marque, qui combine fidélité comportementale, attachement affectif, appartenance et engagement actif.", "sources": [{"documentId": "com", "page": 14}]}, {"id": "communication-concept-068", "chapter": "5 · L’image de marque", "question": "Qu’est-ce que la dissonance entre identité et image de marque ?", "answer": "C’est un décalage entre ce que la marque veut exprimer et la façon dont elle est réellement perçue.", "sources": [{"documentId": "com", "page": 15}]}, {"id": "communication-concept-069", "chapter": "5 · L’image de marque", "question": "Qu’est-ce qu’un bad buzz ?", "answer": "C’est la propagation rapide de réactions négatives qui peut dégrader l’image et la réputation d’une marque.", "sources": [{"documentId": "com", "page": 15}]}, {"id": "communication-concept-070", "chapter": "5 · L’image de marque", "question": "Qu’est-ce que le greenwashing ou le social washing ?", "answer": "C’est le fait de revendiquer des engagements environnementaux ou sociaux peu sincères, trompeurs ou insuffisamment soutenus par les pratiques réelles.", "sources": [{"documentId": "com", "page": 15}]}, {"id": "communication-concept-071", "chapter": "3 · Les théories", "question": "Quels sont les trois stades de la hiérarchie des effets, dans l’ordre ?", "answer": "Cognitif, affectif, puis conatif : le consommateur apprend, développe une attitude, puis passe à l’action.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-072", "chapter": "3 · Les théories", "question": "Quelles étapes de la hiérarchie des effets appartiennent au stade cognitif ?", "answer": "La prise de conscience et la connaissance : découvrir l’existence de la marque ou du produit, puis acquérir des informations.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-073", "chapter": "3 · Les théories", "question": "Quelles étapes de la hiérarchie des effets appartiennent au stade affectif ?", "answer": "L’appréciation et la préférence : former une opinion ou un ressenti, puis comparer les marques et en préférer une.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-074", "chapter": "3 · Les théories", "question": "Quelles étapes de la hiérarchie des effets appartiennent au stade conatif ?", "answer": "La conviction et l’achat : être persuadé que le produit constitue le bon choix, puis agir et l’acheter.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-075", "chapter": "3 · Les théories", "question": "Que signifie la prise de conscience dans la hiérarchie des effets ?", "answer": "Le consommateur découvre l’existence du produit ou de la marque. C’est la première étape du stade cognitif.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-076", "chapter": "3 · Les théories", "question": "Que signifie la connaissance dans la hiérarchie des effets ?", "answer": "Le consommateur acquiert des informations sur le produit ou la marque, au-delà de la simple découverte de son existence.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-077", "chapter": "3 · Les théories", "question": "Que signifie l’appréciation dans la hiérarchie des effets ?", "answer": "Le consommateur forme une opinion ou un ressenti positif ou négatif envers la marque. Cette étape appartient au stade affectif.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-078", "chapter": "3 · Les théories", "question": "Que signifie la préférence dans la hiérarchie des effets ?", "answer": "Le consommateur compare les marques et choisit celle qu’il préfère. Cette étape appartient au stade affectif.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-079", "chapter": "3 · Les théories", "question": "Que signifie la conviction dans la hiérarchie des effets ?", "answer": "Le consommateur est persuadé que le produit ou la marque représente le bon choix. Cette étape précède l’achat dans le stade conatif.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-080", "chapter": "3 · Les théories", "question": "À quelle étape la hiérarchie des effets débouche-t-elle sur un comportement d’achat ?", "answer": "À la dernière étape, l’achat : le consommateur agit effectivement. Elle suit la conviction et relève du stade conatif.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-081", "chapter": "3 · Les théories", "question": "Pourquoi le consommateur ne passe-t-il pas directement de l’ignorance à l’achat ?", "answer": "L’achat résulte d’un processus progressif : il acquiert des informations, forme une attitude, développe une conviction, puis agit.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-082", "chapter": "3 · Les théories", "question": "À quoi sert la hiérarchie des effets pour préparer une campagne ?", "answer": "À repérer l’étape où se trouve la cible et à adapter l’objectif, le message, les contenus et les canaux : informer, séduire ou inciter à agir.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-083", "chapter": "3 · Les théories", "question": "Quel type de campagne correspond à chacun des trois stades de la hiérarchie des effets ?", "answer": "Cognitif : campagne informative. Affectif : campagne d’image. Conatif : campagne promotionnelle.", "sources": [{"documentId": "com", "page": 16}]}, {"id": "communication-concept-084", "chapter": "3 · Les théories", "question": "Quelle différence y a-t-il entre AIDA et la hiérarchie des effets à six étapes ?", "answer": "AIDA distingue attention, intérêt, désir et achat. La hiérarchie des effets détaille prise de conscience, connaissance, appréciation, préférence, conviction et achat, regroupées en trois stades.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-085", "chapter": "5 · L’image de marque", "question": "Qu’est-ce que l’identité de marque ?", "answer": "C’est ce que la marque veut dire d’elle-même : son ADN, sa mission et ses valeurs.", "sources": [{"documentId": "com", "page": 13}]}, {"id": "communication-concept-086", "chapter": "5 · L’image de marque", "question": "Qu’est-ce que l’image de marque ?", "answer": "C’est ce que les consommateurs perçoivent réellement de la marque : la représentation mentale qu’ils s’en font.", "sources": [{"documentId": "com", "page": 13}]}, {"id": "communication-concept-087", "chapter": "5 · L’image de marque", "question": "Qu’est-ce que la réputation d’une marque ?", "answer": "C’est l’image qui se construit dans la durée, façonnée par les expériences, le bouche-à-oreille et les médias.", "sources": [{"documentId": "com", "page": 13}]}, {"id": "communication-concept-088", "chapter": "5 · L’image de marque", "question": "Quelle différence y a-t-il entre l’identité voulue et l’image perçue ?", "answer": "L’identité correspond à ce que la marque veut exprimer. L’image correspond à ce que les consommateurs en retiennent réellement. Les deux peuvent être différentes.", "sources": [{"documentId": "com", "page": 13}]}, {"id": "communication-concept-089", "chapter": "5 · L’image de marque", "question": "Quelle différence y a-t-il entre image et réputation de marque ?", "answer": "L’image est la représentation mentale perçue par les consommateurs. La réputation insiste sur sa construction dans la durée à travers l’expérience, les médias et le bouche-à-oreille.", "sources": [{"documentId": "com", "page": 13}]}, {"id": "communication-concept-090", "chapter": "5 · L’image de marque", "question": "Quels facteurs façonnent la réputation d’une marque dans la durée ?", "answer": "Les expériences avec la marque, le bouche-à-oreille et les médias.", "sources": [{"documentId": "com", "page": 13}]}, {"id": "communication-concept-091", "chapter": "5 · L’image de marque", "question": "Pourquoi une marque ne peut-elle pas changer son image uniquement par la communication ?", "answer": "Sa communication doit être cohérente avec les actions et l’expérience proposées. Le cours souligne qu’il faut aussi agir sur les 4P, faute de quoi l’image perçue peut rester éloignée de l’identité voulue.", "sources": [{"documentId": "com", "page": 15}]}, {"id": "communication-concept-092", "chapter": "5 · L’image de marque", "question": "Quels éléments définissent l’identité d’une marque ?", "answer": "Son ADN, sa mission et ses valeurs : ce qu’elle veut être et dire d’elle-même.", "sources": [{"documentId": "com", "page": 13}]}, {"id": "communication-concept-093", "chapter": "5 · L’image de marque", "question": "Quelles sont les grandes composantes de l’image de marque présentées dans le cours ?", "answer": "Les valeurs et l’univers symbolique, la personnalité de marque, les signes visuels et identitaires, et le storytelling.", "sources": [{"documentId": "com", "page": 13}]}, {"id": "communication-concept-094", "chapter": "2 · La stratégie", "question": "Que faut-il faire avant de construire une stratégie de communication ?", "answer": "Faire de la veille, dresser un constat et observer la cible pour comprendre sa situation. La stratégie vient ensuite, à partir de ce diagnostic.", "sources": [{"documentId": "com", "page": 16}]}, {"id": "communication-concept-095", "chapter": "2 · La stratégie", "question": "Quelle question de départ aide à comprendre les obstacles à l’achat ?", "answer": "« Pourquoi le consommateur n’achète-t-il pas mon produit ? » Elle guide l’observation des motivations, des freins, des besoins et des attentes avant de construire la stratégie.", "sources": [{"documentId": "com", "page": 16}]}, {"id": "communication-concept-096", "chapter": "2 · La stratégie", "question": "Quels sont les deux sens du mot insight indiqués dans le cours ?", "answer": "Une motivation ou un besoin sous-jacent, et un signe avant-coureur. La définition à retenir relie l’insight à un problème ou un dilemme irrésolu perçu dans une catégorie de produits.", "sources": [{"documentId": "com", "page": 16}]}, {"id": "communication-concept-097", "chapter": "2 · La stratégie", "question": "Comment analyser un insight en quatre temps ?", "answer": "Observation, motivation, frein, puis réponse de la marque : partir du constat, comprendre ce qui attire et ce qui bloque, puis proposer une réponse adaptée.", "sources": [{"documentId": "com", "page": 6}]}, {"id": "communication-concept-098", "chapter": "2 · La stratégie", "question": "Quelle différence y a-t-il entre une motivation et un frein à l’achat ?", "answer": "La motivation pousse le consommateur à agir ou à acheter. Le frein fait obstacle à cette action. Il faut étudier les deux pour comprendre la cible.", "sources": [{"documentId": "com", "page": 6}]}, {"id": "communication-concept-099", "chapter": "2 · La stratégie", "question": "Qu’est-ce qu’une motivation hédoniste ?", "answer": "La recherche du plaisir pour soi : se faire plaisir grâce à l’achat ou à l’utilisation du produit.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-100", "chapter": "2 · La stratégie", "question": "Qu’est-ce qu’une motivation oblative ?", "answer": "La volonté de faire plaisir à une autre personne, plutôt que de rechercher uniquement son propre plaisir.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-101", "chapter": "2 · La stratégie", "question": "Qu’est-ce qu’une motivation d’auto-expression ?", "answer": "La volonté d’exprimer sa personnalité, ses valeurs ou l’image que l’on veut donner de soi à travers sa consommation.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-102", "chapter": "2 · La stratégie", "question": "Quels éléments faut-il étudier en plus des motivations et des freins ?", "answer": "Les besoins, les attentes et la perception de la cible. Ils complètent la compréhension de son comportement.", "sources": [{"documentId": "com", "page": 6}]}, {"id": "communication-concept-103", "chapter": "2 · La stratégie", "question": "Pourquoi observer la cible avant de choisir le message ?", "answer": "Pour partir de ses problèmes, motivations et obstacles réels, puis construire une stratégie et un message adaptés à ce qu’elle vit.", "sources": [{"documentId": "com", "page": 16}]}, {"id": "communication-concept-104", "chapter": "2 · La stratégie", "question": "Quelles données de profil faut-il recueillir sur le client idéal ?", "answer": "Son âge, son sexe, sa profession et son salaire.", "sources": [{"documentId": "com", "page": 16}]}, {"id": "communication-concept-105", "chapter": "2 · La stratégie", "question": "Quelles informations faut-il recueillir sur les centres d’intérêt du client idéal ?", "answer": "Ses intérêts, ses passions et ce qu’il fait de son temps libre.", "sources": [{"documentId": "com", "page": 16}]}, {"id": "communication-concept-106", "chapter": "2 · La stratégie", "question": "Quelles difficultés faut-il identifier chez le client idéal ?", "answer": "Ses problèmes, ses obstacles et ses frustrations.", "sources": [{"documentId": "com", "page": 16}]}, {"id": "communication-concept-107", "chapter": "2 · La stratégie", "question": "Quelle situation future faut-il décrire pour comprendre le client idéal ?", "answer": "À quoi ressemblera sa vie une fois son problème résolu : le changement et les bénéfices qu’il recherche.", "sources": [{"documentId": "com", "page": 16}]}, {"id": "communication-concept-108", "chapter": "2 · La stratégie", "question": "Quelles informations émotionnelles faut-il recueillir sur le client idéal ?", "answer": "Ses motivations profondes et les émotions qu’il traverse.", "sources": [{"documentId": "com", "page": 16}]}, {"id": "communication-concept-109", "chapter": "2 · La stratégie", "question": "Quels éléments de langage faut-il relever chez le client idéal ?", "answer": "Son vocabulaire et ses expressions, pour comprendre sa manière de parler de ses besoins et de ses problèmes.", "sources": [{"documentId": "com", "page": 16}]}, {"id": "communication-concept-110", "chapter": "2 · La stratégie", "question": "Quelles sources permettent de mieux connaître le client idéal ?", "answer": "Les études marketing existantes, les discussions et retours des clients, les outils publicitaires, les forums, les commentaires et les avis.", "sources": [{"documentId": "com", "page": 6}]}, {"id": "communication-concept-111", "chapter": "2 · La stratégie", "question": "Quels rôles faut-il distinguer dans le processus de décision d’achat ?", "answer": "Le consommateur, l’acheteur et les prescripteurs. Ces rôles peuvent être tenus par des personnes différentes et influencent la hiérarchisation des cibles.", "sources": [{"documentId": "com", "page": 6}]}, {"id": "communication-concept-112", "chapter": "2 · La stratégie", "question": "Quels critères permettent de décrire concrètement une cible principale ?", "answer": "L’âge, le sexe, le lieu géographique, les centres d’intérêt et la catégorie socioprofessionnelle.", "sources": [{"documentId": "com", "page": 6}]}, {"id": "communication-concept-113", "chapter": "2 · La stratégie", "question": "Pourquoi la cible de communication peut-elle dépasser les personnes qui achètent ?", "answer": "L’entreprise peut aussi s’adresser à des personnes qui recommandent, relaient ou influencent l’achat, comme les prescripteurs et les distributeurs.", "sources": [{"documentId": "com", "page": 4}]}, {"id": "communication-concept-114", "chapter": "2 · La stratégie", "question": "À quelles cinq questions une stratégie de communication doit-elle répondre ?", "answer": "Quoi dire, comment le dire, à qui, quand et pourquoi. Il faut adresser le bon message à la bonne cible par le bon canal.", "sources": [{"documentId": "com", "page": 3}]}, {"id": "communication-concept-115", "chapter": "2 · La stratégie", "question": "Que doit contenir le diagnostic avant de fixer la stratégie de communication ?", "answer": "Une analyse interne, une analyse externe et une analyse concurrentielle : forces, faiblesses, opportunités, menaces, comportements des consommateurs et communication des concurrents.", "sources": [{"documentId": "com", "page": 3}]}, {"id": "communication-concept-116", "chapter": "2 · La stratégie", "question": "Comment formuler une problématique de communication selon le cours ?", "answer": "Sous la forme « Comment… alors que… ? », en reliant l’objectif recherché à la difficulté mise en évidence par le diagnostic.", "sources": [{"documentId": "com", "page": 3}]}, {"id": "communication-concept-117", "chapter": "2 · La stratégie", "question": "Quel lien unit le positionnement et le message publicitaire ?", "answer": "Le marketing définit le positionnement. La communication en déduit le message à transmettre, en tenant compte de l’objectif et de la cible.", "sources": [{"documentId": "com", "page": 7}]}, {"id": "communication-concept-118", "chapter": "2 · La stratégie", "question": "Quelles qualités doit avoir la promesse d’une copy stratégie ?", "answer": "Elle doit être unique, simple et suffisamment abstraite pour laisser de la liberté à la création.", "sources": [{"documentId": "com", "page": 7}]}, {"id": "communication-concept-119", "chapter": "2 · La stratégie", "question": "Quelle différence y a-t-il entre une promesse publicitaire et une preuve ?", "answer": "La promesse annonce ce que la marque apporte au consommateur. La preuve fournit les éléments concrets qui justifient cette promesse.", "sources": [{"documentId": "com", "page": 7}]}, {"id": "communication-concept-120", "chapter": "2 · La stratégie", "question": "Sur quel bénéfice la création doit-elle reposer dans une copy stratégie ?", "answer": "Un bénéfice tangible, simple, clair et cohérent. La copy stratégie fixe le cadre dans lequel la création se développe.", "sources": [{"documentId": "com", "page": 7}]}, {"id": "communication-concept-121", "chapter": "3 · Les théories", "question": "Qu’est-ce que le signifiant ?", "answer": "La forme perceptible du signe : ce que l’on voit ou entend, avant d’interpréter le sens associé.", "sources": [{"documentId": "com", "page": 10}]}, {"id": "communication-concept-122", "chapter": "3 · Les théories", "question": "Qu’est-ce que le signifié ?", "answer": "Le sens, le concept ou le symbole associé au signifiant.", "sources": [{"documentId": "com", "page": 16}]}, {"id": "communication-concept-123", "chapter": "3 · Les théories", "question": "Comment analyser un message à l’aide de la sémiologie ?", "answer": "Repérer les signes et leurs signifiants, identifier les sens associés, distinguer dénotation et connotation, puis examiner les interprétations possibles selon la cible.", "sources": [{"documentId": "com", "page": 10}]}, {"id": "communication-concept-124", "chapter": "3 · Les théories", "question": "Pourquoi un même signe peut-il être compris différemment selon les publics ?", "answer": "Son interprétation peut être subjective et dépendre de la culture. Un signe polysémique peut recevoir plusieurs sens, d’où un risque de décalage entre le sens voulu et le sens perçu.", "sources": [{"documentId": "com", "page": 10}]}, {"id": "communication-concept-125", "chapter": "3 · Les théories", "question": "À quoi sert le modèle de Lasswell pour analyser une communication ?", "answer": "À identifier l’émetteur, le message, la cible, le canal et l’effet recherché, grâce aux questions « Qui dit quoi, à qui, par quel canal, avec quel effet ? ».", "sources": [{"documentId": "com", "page": 7}]}, {"id": "communication-concept-126", "chapter": "3 · Les théories", "question": "Quel rôle la rétroaction joue-t-elle dans la communication ?", "answer": "Elle apporte des informations en retour sur les effets et l’état du système. Elle permet de mesurer, d’ajuster et de réguler la communication.", "sources": [{"documentId": "com", "page": 8}]}, {"id": "communication-concept-127", "chapter": "3 · Les théories", "question": "Quelle différence y a-t-il entre le contenu et la relation dans un message ?", "answer": "Le contenu est ce qui est dit. La relation correspond à la manière dont c’est dit et à la relation qui se construit entre les interlocuteurs.", "sources": [{"documentId": "com", "page": 8}]}, {"id": "communication-concept-128", "chapter": "3 · Les théories", "question": "Quels éléments non verbaux transmettent aussi un sens selon Palo Alto ?", "answer": "Les gestes, les images, les couleurs, mais aussi le silence et la posture. La communication dépasse les seuls mots.", "sources": [{"documentId": "com", "page": 8}]}, {"id": "communication-concept-129", "chapter": "3 · Les théories", "question": "Quelles notions faut-il mobiliser dans l’étude de cas annoncée au partiel ?", "answer": "Les théories de la communication, la sémiologie, les stratégies de communication et la copy stratégie, en reliant chaque notion aux éléments du cas.", "sources": [{"documentId": "com", "page": 15}]}, {"id": "communication-concept-130", "chapter": "1 · Les fondamentaux", "question": "Quelle différence y a-t-il entre communication d’entreprise et communication commerciale ?", "answer": "La communication d’entreprise comprend tous les messages, informations et signaux émis, volontairement ou non, vers ses publics. La communication commerciale regroupe les actions visant à influencer positivement leurs attitudes et comportements dans un objectif de performance économique.", "sources": [{"documentId": "com", "page": 1}]}], "documents": ["com"], "legacyCardIds": ["communication-concept-001", "communication-concept-002", "communication-concept-003", "communication-concept-004", "communication-concept-005", "communication-concept-006", "communication-concept-007", "communication-concept-008", "communication-concept-009", "communication-concept-010", "communication-concept-011", "communication-concept-012", "communication-concept-013", "communication-concept-014", "communication-concept-015", "communication-concept-016", "communication-concept-017", "communication-concept-018", "communication-concept-019", "communication-concept-020", "communication-concept-021", "communication-concept-022", "communication-concept-023", "communication-concept-024", "communication-concept-025", "communication-concept-026", "communication-concept-027", "communication-concept-028", "communication-concept-029", "communication-concept-030", "communication-concept-031", "communication-concept-032", "communication-concept-033", "communication-concept-034", "communication-concept-035", "communication-concept-036", "communication-concept-037", "communication-concept-038", "communication-concept-039", "communication-concept-040", "communication-concept-041", "communication-concept-042", "communication-concept-043", "communication-concept-044", "communication-concept-045", "communication-concept-046", "communication-concept-047", "communication-concept-048", "communication-concept-049", "communication-concept-050", "communication-concept-051", "communication-concept-052", "communication-concept-053", "communication-concept-054", "communication-concept-055", "communication-concept-056", "communication-concept-057", "communication-concept-058", "communication-concept-059", "communication-concept-060", "communication-concept-061", "communication-concept-062", "communication-concept-063", "communication-concept-064", "communication-concept-065", "communication-concept-066", "communication-concept-067", "communication-concept-068", "communication-concept-069", "communication-concept-070"], "subjectId": "communication", "subjectTitle": "Communication commerciale", "quizTitle": "Tout le cours", "variant": "complete"}, {"subjectId": "communication", "subjectTitle": "Communication commerciale", "symbol": "C", "documents": ["com"], "id": "communication-essentiel", "title": "Communication commerciale · L’essentiel", "quizTitle": "L’essentiel", "variant": "essential", "description": "Notions signalées pour le partiel : définitions, hiérarchie des effets, identité/image/réputation, cibles, insight, théories, sémiologie et copy stratégie.", "storageKey": "declic-communication-essentiel-v1", "cards": [{"id": "communication-concept-001", "chapter": "1 · Les fondamentaux", "question": "Quelle est la définition de la communication d’une entreprise ?", "answer": "C’est l’ensemble des informations, messages et signaux qu’une entreprise émet, volontairement ou non, vers tous ses publics.", "sources": [{"documentId": "com", "page": 1}]}, {"id": "communication-concept-002", "chapter": "1 · Les fondamentaux", "question": "Quelle est la définition de la communication commerciale ?", "answer": "C’est l’ensemble des actions visant à influencer positivement les attitudes et comportements des publics dans une perspective de performance économique.", "sources": [{"documentId": "com", "page": 1}]}, {"id": "communication-concept-003", "chapter": "1 · Les fondamentaux", "question": "Quelles sont les quatre fonctions de la communication commerciale ?", "answer": "Informer, séduire, convaincre et fidéliser.", "sources": [{"documentId": "com", "page": 1}]}, {"id": "communication-concept-013", "chapter": "2 · La stratégie", "question": "Quelle est la définition d’une stratégie de communication ?", "answer": "C’est l’ensemble des choix et orientations qui guident les actions de communication pour atteindre des objectifs précis auprès de cibles identifiées.", "sources": [{"documentId": "com", "page": 3}]}, {"id": "communication-concept-014", "chapter": "2 · La stratégie", "question": "Quelles sont les quatre étapes d’une stratégie de communication ?", "answer": "Diagnostic, objectifs de communication, cibles, puis positionnement et message ou stratégie créative.", "sources": [{"documentId": "com", "page": 6}]}, {"id": "communication-concept-016", "chapter": "2 · La stratégie", "question": "Quels sont les trois objectifs de communication ?", "answer": "Cognitif : faire savoir ou connaître. Affectif : faire aimer. Conatif : faire agir.", "sources": [{"documentId": "com", "page": 6}]}, {"id": "communication-concept-018", "chapter": "2 · La stratégie", "question": "Quelle différence y a-t-il entre cible marketing et cible de communication ?", "answer": "La cible marketing désigne les personnes à qui l’entreprise vend. La cible de communication désigne les personnes à qui elle s’adresse.", "sources": [{"documentId": "com", "page": 6}]}, {"id": "communication-concept-022", "chapter": "2 · La stratégie", "question": "Qu’est-ce qu’un insight consommateur ?", "answer": "C’est la perception d’un problème ou d’un dilemme non résolu dans une catégorie de produits. Il révèle une motivation, un besoin ou un manque.", "sources": [{"documentId": "com", "page": 6}]}, {"id": "communication-concept-023", "chapter": "2 · La stratégie", "question": "Quelles sont les trois grandes motivations du consommateur ?", "answer": "Hédonistes : se faire plaisir. Oblatives : faire plaisir aux autres. Auto-expression : exprimer sa personnalité ou l’image de soi.", "sources": [{"documentId": "com", "page": 6}]}, {"id": "communication-concept-024", "chapter": "2 · La stratégie", "question": "Quels sont les principaux freins à l’achat ?", "answer": "Les peurs, les inhibitions et les risques perçus.", "sources": [{"documentId": "com", "page": 6}]}, {"id": "communication-concept-026", "chapter": "2 · La stratégie", "question": "Qu’est-ce qu’une copy stratégie ?", "answer": "C’est un brief créatif qui synthétise la réflexion stratégique et fixe ce que le message doit communiquer.", "sources": [{"documentId": "com", "page": 7}]}, {"id": "communication-concept-027", "chapter": "2 · La stratégie", "question": "Quels sont les éléments d’une copy stratégie ?", "answer": "Promesse, bénéfice consommateur, avantage produit, ton, preuves et contraintes.", "sources": [{"documentId": "com", "page": 7}]}, {"id": "communication-concept-028", "chapter": "2 · La stratégie", "question": "Qu’est-ce que la promesse publicitaire ?", "answer": "C’est ce que la marque promet d’apporter au consommateur. Elle doit être unique, simple et ne pas enfermer la création.", "sources": [{"documentId": "com", "page": 7}]}, {"id": "communication-concept-029", "chapter": "2 · La stratégie", "question": "Quelle différence y a-t-il entre bénéfice consommateur et avantage produit ?", "answer": "Le bénéfice est ce que le consommateur retire de l’usage. L’avantage produit est une performance ou caractéristique du produit.", "sources": [{"documentId": "com", "page": 7}]}, {"id": "communication-concept-030", "chapter": "2 · La stratégie", "question": "Qu’est-ce que le ton d’un message publicitaire ?", "answer": "C’est le climat ou l’atmosphère du message : informatif, démonstratif, humoristique, imaginaire ou symbolique, notamment.", "sources": [{"documentId": "com", "page": 7}]}, {"id": "communication-concept-031", "chapter": "2 · La stratégie", "question": "À quoi servent les preuves dans une copy stratégie ?", "answer": "Elles justifient la promesse par des éléments concrets.", "sources": [{"documentId": "com", "page": 7}]}, {"id": "communication-concept-032", "chapter": "2 · La stratégie", "question": "Quelles contraintes encadrent une copy stratégie ?", "answer": "Les contraintes peuvent être légales, temporelles, budgétaires ou liées à la charte graphique.", "sources": [{"documentId": "com", "page": 7}]}, {"id": "communication-concept-033", "chapter": "3 · Les théories", "question": "Quels sont les éléments du modèle de Lasswell ?", "answer": "L’émetteur, le message, la cible, le canal et l’effet. Le modèle se résume par « Qui dit quoi, à qui, par quel canal, avec quel effet ? ».", "sources": [{"documentId": "com", "page": 7}]}, {"id": "communication-concept-034", "chapter": "3 · Les théories", "question": "Quelle est la principale limite du modèle de Shannon et Weaver présenté dans le cours ?", "answer": "C’est un modèle linéaire ou télégraphique qui ne prend pas en compte la rétroaction.", "sources": [{"documentId": "com", "page": 8}]}, {"id": "communication-concept-035", "chapter": "3 · Les théories", "question": "Quelles sont les six fonctions du langage de Jakobson ?", "answer": "Référentielle, expressive, conative, phatique, poétique et métalinguistique.", "sources": [{"documentId": "com", "page": 8}]}, {"id": "communication-concept-036", "chapter": "3 · Les théories", "question": "Qu’est-ce que la rétroaction ?", "answer": "C’est le retour d’information qui permet à un système de connaître son état et de se réguler.", "sources": [{"documentId": "com", "page": 8}]}, {"id": "communication-concept-038", "chapter": "3 · Les théories", "question": "Quel principe fondamental retient-on de l’école de Palo Alto ?", "answer": "On ne peut pas ne pas communiquer : les comportements et le non-verbal transmettent aussi des messages.", "sources": [{"documentId": "com", "page": 8}]}, {"id": "communication-concept-039", "chapter": "3 · Les théories", "question": "Quels sont les deux niveaux d’un message selon Palo Alto ?", "answer": "Le contenu, c’est-à-dire ce qui est dit, et la relation, c’est-à-dire la manière dont c’est dit.", "sources": [{"documentId": "com", "page": 8}]}, {"id": "communication-concept-040", "chapter": "3 · Les théories", "question": "Que signifient logos, pathos et ethos ?", "answer": "Logos : persuasion par la raison et la démonstration. Pathos : persuasion par l’émotion. Ethos : persuasion par le statut et la crédibilité de l’émetteur.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-041", "chapter": "3 · Les théories", "question": "Qu’est-ce que le modèle behavioriste ?", "answer": "Il explique les comportements comme des réponses à des stimuli extérieurs. La répétition et la nature des stimuli favorisent le conditionnement.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-042", "chapter": "3 · Les théories", "question": "Que signifie AIDA ?", "answer": "Attention, intérêt, désir, achat.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-043", "chapter": "3 · Les théories", "question": "Quelles sont les six étapes de la hiérarchie des effets ?", "answer": "Prise de conscience, connaissance, appréciation, préférence, conviction et achat.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-044", "chapter": "3 · Les théories", "question": "Qu’est-ce que le storytelling ?", "answer": "C’est l’art de raconter une histoire pour susciter l’émotion, donner du sens et convaincre.", "sources": [{"documentId": "com", "page": 10}]}, {"id": "communication-concept-045", "chapter": "3 · Les théories", "question": "Qu’est-ce que le two-step flow of communication ?", "answer": "C’est une diffusion de la communication en deux temps, dans laquelle les leaders d’opinion jouent un rôle de relais et d’influence.", "sources": [{"documentId": "com", "page": 10}]}, {"id": "communication-concept-046", "chapter": "3 · Les théories", "question": "Qu’est-ce que la sémiotique ?", "answer": "C’est la science générale des signes.", "sources": [{"documentId": "com", "page": 10}]}, {"id": "communication-concept-047", "chapter": "3 · Les théories", "question": "Quelle différence y a-t-il entre signifiant et signifié ?", "answer": "Le signifiant est la forme perceptible du signe. Le signifié est le sens ou le concept qui lui est associé.", "sources": [{"documentId": "com", "page": 10}]}, {"id": "communication-concept-048", "chapter": "3 · Les théories", "question": "Quelle différence y a-t-il entre dénotation et connotation ?", "answer": "La dénotation correspond au sens directement décrit. La connotation renvoie aux significations et valeurs subjectives associées au signe.", "sources": [{"documentId": "com", "page": 10}]}, {"id": "communication-concept-049", "chapter": "3 · Les théories", "question": "Qu’est-ce qu’un signe polysémique ?", "answer": "C’est un signe qui peut recevoir plusieurs significations ou interprétations.", "sources": [{"documentId": "com", "page": 10}]}, {"id": "communication-concept-060", "chapter": "5 · L’image de marque", "question": "Quelle différence y a-t-il entre identité, image et réputation de marque ?", "answer": "L’identité est ce que la marque veut exprimer. L’image est la représentation que les publics se font d’elle. La réputation se construit dans la durée à partir des opinions et expériences.", "sources": [{"documentId": "com", "page": 13}]}, {"id": "communication-concept-068", "chapter": "5 · L’image de marque", "question": "Qu’est-ce que la dissonance entre identité et image de marque ?", "answer": "C’est un décalage entre ce que la marque veut exprimer et la façon dont elle est réellement perçue.", "sources": [{"documentId": "com", "page": 15}]}, {"id": "communication-concept-069", "chapter": "5 · L’image de marque", "question": "Qu’est-ce qu’un bad buzz ?", "answer": "C’est la propagation rapide de réactions négatives qui peut dégrader l’image et la réputation d’une marque.", "sources": [{"documentId": "com", "page": 15}]}, {"id": "communication-concept-070", "chapter": "5 · L’image de marque", "question": "Qu’est-ce que le greenwashing ou le social washing ?", "answer": "C’est le fait de revendiquer des engagements environnementaux ou sociaux peu sincères, trompeurs ou insuffisamment soutenus par les pratiques réelles.", "sources": [{"documentId": "com", "page": 15}]}, {"id": "communication-concept-071", "chapter": "3 · Les théories", "question": "Quels sont les trois stades de la hiérarchie des effets, dans l’ordre ?", "answer": "Cognitif, affectif, puis conatif : le consommateur apprend, développe une attitude, puis passe à l’action.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-072", "chapter": "3 · Les théories", "question": "Quelles étapes de la hiérarchie des effets appartiennent au stade cognitif ?", "answer": "La prise de conscience et la connaissance : découvrir l’existence de la marque ou du produit, puis acquérir des informations.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-073", "chapter": "3 · Les théories", "question": "Quelles étapes de la hiérarchie des effets appartiennent au stade affectif ?", "answer": "L’appréciation et la préférence : former une opinion ou un ressenti, puis comparer les marques et en préférer une.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-074", "chapter": "3 · Les théories", "question": "Quelles étapes de la hiérarchie des effets appartiennent au stade conatif ?", "answer": "La conviction et l’achat : être persuadé que le produit constitue le bon choix, puis agir et l’acheter.", "sources": [{"documentId": "com", "page": 9}]}, {"id": "communication-concept-083", "chapter": "3 · Les théories", "question": "Quel type de campagne correspond à chacun des trois stades de la hiérarchie des effets ?", "answer": "Cognitif : campagne informative. Affectif : campagne d’image. Conatif : campagne promotionnelle.", "sources": [{"documentId": "com", "page": 16}]}, {"id": "communication-concept-085", "chapter": "5 · L’image de marque", "question": "Qu’est-ce que l’identité de marque ?", "answer": "C’est ce que la marque veut dire d’elle-même : son ADN, sa mission et ses valeurs.", "sources": [{"documentId": "com", "page": 13}]}, {"id": "communication-concept-086", "chapter": "5 · L’image de marque", "question": "Qu’est-ce que l’image de marque ?", "answer": "C’est ce que les consommateurs perçoivent réellement de la marque : la représentation mentale qu’ils s’en font.", "sources": [{"documentId": "com", "page": 13}]}, {"id": "communication-concept-087", "chapter": "5 · L’image de marque", "question": "Qu’est-ce que la réputation d’une marque ?", "answer": "C’est l’image qui se construit dans la durée, façonnée par les expériences, le bouche-à-oreille et les médias.", "sources": [{"documentId": "com", "page": 13}]}, {"id": "communication-concept-094", "chapter": "2 · La stratégie", "question": "Que faut-il faire avant de construire une stratégie de communication ?", "answer": "Faire de la veille, dresser un constat et observer la cible pour comprendre sa situation. La stratégie vient ensuite, à partir de ce diagnostic.", "sources": [{"documentId": "com", "page": 16}]}, {"id": "communication-concept-095", "chapter": "2 · La stratégie", "question": "Quelle question de départ aide à comprendre les obstacles à l’achat ?", "answer": "« Pourquoi le consommateur n’achète-t-il pas mon produit ? » Elle guide l’observation des motivations, des freins, des besoins et des attentes avant de construire la stratégie.", "sources": [{"documentId": "com", "page": 16}]}, {"id": "communication-concept-096", "chapter": "2 · La stratégie", "question": "Quels sont les deux sens du mot insight indiqués dans le cours ?", "answer": "Une motivation ou un besoin sous-jacent, et un signe avant-coureur. La définition à retenir relie l’insight à un problème ou un dilemme irrésolu perçu dans une catégorie de produits.", "sources": [{"documentId": "com", "page": 16}]}, {"id": "communication-concept-097", "chapter": "2 · La stratégie", "question": "Comment analyser un insight en quatre temps ?", "answer": "Observation, motivation, frein, puis réponse de la marque : partir du constat, comprendre ce qui attire et ce qui bloque, puis proposer une réponse adaptée.", "sources": [{"documentId": "com", "page": 6}]}, {"id": "communication-concept-104", "chapter": "2 · La stratégie", "question": "Quelles données de profil faut-il recueillir sur le client idéal ?", "answer": "Son âge, son sexe, sa profession et son salaire.", "sources": [{"documentId": "com", "page": 16}]}, {"id": "communication-concept-105", "chapter": "2 · La stratégie", "question": "Quelles informations faut-il recueillir sur les centres d’intérêt du client idéal ?", "answer": "Ses intérêts, ses passions et ce qu’il fait de son temps libre.", "sources": [{"documentId": "com", "page": 16}]}, {"id": "communication-concept-106", "chapter": "2 · La stratégie", "question": "Quelles difficultés faut-il identifier chez le client idéal ?", "answer": "Ses problèmes, ses obstacles et ses frustrations.", "sources": [{"documentId": "com", "page": 16}]}, {"id": "communication-concept-107", "chapter": "2 · La stratégie", "question": "Quelle situation future faut-il décrire pour comprendre le client idéal ?", "answer": "À quoi ressemblera sa vie une fois son problème résolu : le changement et les bénéfices qu’il recherche.", "sources": [{"documentId": "com", "page": 16}]}, {"id": "communication-concept-108", "chapter": "2 · La stratégie", "question": "Quelles informations émotionnelles faut-il recueillir sur le client idéal ?", "answer": "Ses motivations profondes et les émotions qu’il traverse.", "sources": [{"documentId": "com", "page": 16}]}, {"id": "communication-concept-109", "chapter": "2 · La stratégie", "question": "Quels éléments de langage faut-il relever chez le client idéal ?", "answer": "Son vocabulaire et ses expressions, pour comprendre sa manière de parler de ses besoins et de ses problèmes.", "sources": [{"documentId": "com", "page": 16}]}]}];
